const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const h = (tag, attrs = {}, ...kids) => {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'class') e.className = v; else if (k === 'style') e.style.cssText = v;
    else if (k.startsWith('on')) e.addEventListener(k.slice(2), v); else if (v !== undefined && v !== null && v !== false) e.setAttribute(k, v === true ? '' : v);
  }
  for (const k of kids.flat()) if (k !== null && k !== undefined) e.append(k.nodeType ? k : document.createTextNode(k));
  return e;
};
const media = p => p === '/File_Not_Found.svg' ? p : '/media?path=' + encodeURIComponent(p);      // the File Not Found picture is a program file (Rule 7.24)
// a sound can be a web link to an MP3 (Rule 7.20): the browser plays it straight from the web; anything else is a file on the Brain
const isLink = p => /^https?:\/\//i.test(String(p ?? '').trim());
const soundUrl = p => isLink(p) ? String(p).trim() : media(p);
const noSpaces = n => String(n ?? '').trim().replace(/_*\s+_*/g, '_');
const clone = o => JSON.parse(JSON.stringify(o));
// a background that is not a number is a color ("red", "#3fa34d"); a number only ever picks a picture
const bg = v => (v === '' || v === null || v === undefined || /^\s*-?\d+\s*$/.test(String(v))) ? '' : String(v);
// Background pictures (Fritz, 2026-11-02, Rule 7.10): .background = 1, 2 or 3 shows .backpath, .backpath_2 or .backpath_3;
// 0, blank, a color or any number over 3 shows no background picture. name.image = "path" in a Process sets .backpath and
// background = 1. Every item has at most 3 (Fritz, 2026-11-02).
const IMG_SLOT = /^backpath(?:_(\d+))?$/;
const slotKey = n => n === 1 ? 'backpath' : 'backpath_' + n;
const slotsOf = e => Object.keys(e).filter(k => IMG_SLOT.test(k) && e[k]).map(k => +(IMG_SLOT.exec(k)[1] ?? 1)).sort((a, b) => a - b);
function slotImage(e, v) {
  // in Edit layout the layout being edited wins (a new item has no value yet; a thermowell put on a front IP changes its picture, Rule 5.30)
  const pick = k => editing ? (e[k] ?? v[k]) : (v[k] ?? e[k]);
  const b = String(pick('background') ?? '').trim(), n = /^-?\d+$/.test(b) ? +b : 0;
  return n >= 1 ? (pick(slotKey(n)) ?? '') : '';
}
const hasPictures = (e, v) => !!(slotsOf(e).length || v.backpath || v.backpath_2 || v.backpath_3);

