const V1_GAL = [197, 237];       // Fritz's plain vessel, the One Gallon start (Fritz, 2026-11-05): Proportional uses its Width to Height
const isVW = g => g?.kind === 'vessel' && !!g.vwidget && !g.integrated && isSkyV(g);
