const isStove = g => g?.kind === 'vessel' && (g.vesselType === 'stoveTop' || g.vesselType === 'stoveTopOut');
const isIceCan = g => g?.kind === 'vessel' && g.vesselType === 'iceCan';        // the Ice Water Can (Rule 19.8)
