  const now = S.config.elements.find(e => e.name === name);
  if (!now) return toast(`${name} is gone: nothing saved`, true);
  const out = clone(now);
  for (const key of methodSetKeys(k)) { if (w[key] === undefined) delete out[key]; else out[key] = w[key]; }
