function tapAction(e) {
  if (e.tap && e.tap !== 'default') return e.tap;
  switch (e.type) {
    case 'digitalOut': return isHeatElem(e) ? 'heat' : 'toggle';      // a Heating Element: its pop-up picks the heating method (Rule 6.19)
    case 'switch': return 'toggle';
    case 'pushButton': return 'hold';           // Semi_Widgets_Devices: ON only while held
    case 'pulseButton': return 'pulse';         // one 100 ms ON per tap
    case 'led': return 'none';                  // a light: a Process or its Device controlled sets it
    case 'digitalIn': return ['latch', 'toggle', 'counter'].includes(e.mode) || (e.mode === 'momentary' && simDev(e.device)) ? 'dialog' : simDev(e.device) ? 'toggle' : 'none';
    case 'pwmOut': case 'analogOut': case 'scale': case 'stepper': return 'dialog';
    case 'temperature': return 'setpoint';     // the SetPoint pop-up of the Heating Element that holds what it reads (Rule 2.43)
    case 'analogIn': return simDev(e.device) && !e.sim ? 'dialog' : 'none';
    case 'alarm': return 'acknowledge';
    case 'soundPlayer': return 'toggle';
    case 'fermentor': return 'toggle';         // one click turns the Fermentor Control On or Off (Rules 2.44, 6.30)
    case 'valueWidget': case 'codeValueWidget': case 'timeWidget': case 'dateTimeWidget': return e.readOnly ? 'none' : 'dialog';
    case 'gGlobal':
      if (e.readOnly) return 'none';
      return { switch: 'toggle', pushbutton: 'hold', momentary: 'pulse' }[vkKind(e)] || 'dialog';
    case 'picture': return e.follow ? 'toggle' : 'none';
    case 'manual': return 'manual';
    case PROCESS_WIDGET_TYPE: return 'startStop';      // the Process Widget (Rule 1.31): one click starts or stops its Process
    case 'pwmOut': case 'dutyCycle': case 'hysteresis': case 'pid': case 'deadband': return 'dialog';
    default: return 'none';
  }
}
// a tap on a clone is a tap on its parent
const elByName = n => S.config.elements.find(x => x.name === n) ?? S.config.elements.find(x => x.name === S.config.graphics.find(g => isClone(g) && g.name === n)?.of);
const boolProp = t => t.type === 'alarm' || t.type === 'soundPlayer' ? 'active' : t.type === 'digitalIn' ? 'raw' : isVarEl(t) ? 'value' : 'state';
const isBoolEl = t => ['digitalOut', 'switch', 'pushButton', 'pulseButton', 'led', 'digitalIn', 'alarm', 'soundPlayer', 'fermentor', MANUAL_PUMP_TYPE].includes(t.type) || (isVarEl(t) && t.dataType === 'bool');

// One click on a Method Clone (Rule 4.4) acts as one on its parent, all in unison (Fritz, 2026-11-08: "Clones act just as if it was
// the Parent That all act in Unison. Click One on, ALL on, cLICK ONE OFF , aLL oFF"), no pop-up: shown ON (the parent ON in its
// method), it turns the parent OFF; shown OFF, it switches the parent to its method and turns it ON.
async function methodCloneTap(g) {
  if (!can('operator')) return toast('Your account is view only', true);
  const p = L().elements.find(e => e.name === g.of); if (!p) return;
  const k = heatMethodKey(g.method);
  if (!allowedMethods(p).includes(k)) return toast(`${p.label || p.name} may not use ${heatMethodWord(k)}: switch its Use Method On (Properties, Method Settings, ⬢ ${heatMethodWord(k)})`, true);
  if (NEEDS_PROBE.includes(k) && !p.input) return toast(`${p.label || p.name}: ${heatMethodWord(k)} needs a Temperature Probe (pick one in its Properties)`, true);
  const inMethod = heatMethodKey(S.values[p.name]?.method) === k;
  if (inMethod && S.values[p.name]?.state) return setProp(p.name, 'state', false);
  if (!inMethod) { await setProp(p.name, 'method', heatMethodWord(k)); S.values[p.name] = { ...(S.values[p.name] || {}), method: heatMethodWord(k) }; }
  return setProp(p.name, 'state', true);
}

async function doTap(e) {
  const act = tapAction(e);
  if (!['none', 'workspace'].includes(act) && !can('operator')) return toast('Your account is view only', true);
  const targetName = e.tapTarget || (e.type === 'picture' ? e.follow : e.name);
  // a Heating Element: one click turns it ON or OFF at once in the method it is in, like a Pump (Fritz, 2026-11-08: "Change the Rule
  // Individual elements toggle on off. I really do not like the popup to turn any thing on", Rules 2.33, 2.44). Only an Element set to
  // Ask before changing by hand still asks (ON / OFF buttons). Its method spots and its Temperature Probe's click (Rule 2.43) set the rest.
  const ht = ['heat', 'toggle', 'dialog'].includes(act) && elByName(targetName);
  if (isHeatElem(ht)) {
    const t = ht;
    const cur = !!S.values[t.name]?.state, k = heatMethodKey(S.values[t.name]?.method) ?? startMethod(t);
    let on = !cur;
    if (e.confirm || t.confirm) { const r = await choose(`${S.values[t.name]?.label ?? t.name}`, [['ON', true], ['OFF', false]], cur); if (r === undefined) return; on = r; }
    if (on && NEEDS_PROBE.includes(k) && !t.input) return toast(`${t.label || t.name}: ${heatMethodWord(k)} needs a Temperature Probe (pick one in its Properties)`, true);
    return setProp(t.name, 'state', on);
  }
  if (act === 'none' || act === 'hold') return;          // push and hold buttons work on press / release (below)
  if (act === 'pulse') { const t = elByName(targetName); if (t && isBoolEl(t)) setProp(t.name, boolProp(t), true); return; }
  if (act === 'acknowledge') { if (S.values[e.name]?.active) setProp(e.name, 'active', false); else if (e.type === 'alarm' && e.alarmClass) setProp(e.name, 'active', true); return; }      // an Alarm Widget's hidden .toggle (Rule 7.21): a click turns it Off, or On
  if (act === 'manual') return manualDialog(elByName(targetName) || e);
  if (act === 'workspace') { if (S.config.workspaces.some(w => w.name === targetName)) { wsName = targetName; renderTabs(); renderWs(); } return; }
  if (act === 'startStop') return processWidgetTap(e);
  if (act === 'script') {
    if (e.confirm && !(await choose(`Start process ${targetName}?`, [['Start', true]]))) return;
    try { const r = await api('POST', `/ui/scripts/${encodeURIComponent(targetName)}/start`); if (!r.ok) toast(r.msg, true); else toast(`Started ${targetName}`); } catch (x) { toast(x.message, true); }
    return;
  }
  const t = elByName(targetName); if (!t) return toast(`No Device or Widget "${targetName}"`, true);
  if (t.type === 'temperature') return probeTap(t);      // a Probe, a Thermowell, or a picture that shows one (Rule 2.43)
  if (isHeatElem(t) && (act === 'heat' || act === 'toggle' || act === 'dialog')) return heatDialog(t);
  if ((act === 'toggle' || act === 'dual') && isBoolEl(t)) {      // Dual Action: a click is On / Off (Rule 2.50)
    const cur = t.type === 'digitalIn' ? !!S.values[t.name]?.raw : isOn(t.name);     // simulator: the tap is the switch itself
    if (isConfirmation(t)) return confirmByHand(t, !cur);      // a Confirmation Widget: do it by hand, then Done (Rule 1.28)
    const fs = t.type === 'digitalIn' ? Number(t.forceSecs) || 0 : 0;      // a forced float: ON for a few seconds, then OFF (Panel Update 9, item 12f)
    if (fs > 0 && !cur) { setProp(t.name, 'raw', true); setTimeout(() => setProp(t.name, 'raw', false), fs * 1000); return; }
    if (e.confirm) { const r = await choose(`${S.values[t.name]?.label ?? t.name}`, [['ON', true], ['OFF', false]], cur); if (r === undefined) return; return setProp(t.name, boolProp(t), r); }
    return setProp(t.name, boolProp(t), !cur);
  }
  return valueDialog(t);
}

// Push Button (gGlobal): ON while pressed, OFF when released. "down" repeats every 0.5 s so the server
// lets go by itself if this screen disappears while the button is held.
let held = null;
function release() {
  if (!held) return;
  clearInterval(held.t); held.n.classList.remove('pressed');
  api('POST', '/ui/hold', { name: held.name, down: false }).catch(x => toast(x.message, true));
  held = null;
}
// A Valve or Heating Element set to Push Button (OakBarn Brewery, 2026-11-09, Rule 2.46): On only while its picture is held down, on
// the Tab, built into a Vessel Device or in a Valve Tee; when it is already On, Off only while held (the Brain reverses it).
const isPushHeld = name => { const e = name && elByName(name); return !!e && tapAction(e) === 'hold'; };
// Dual Action (OakBarn Brewery, 2026-11-12, Rule 2.50): held longer than DUAL_HOLD_MS it is a Push Button (On only while held) and the
// click that follows the let go is ignored; let go sooner and it is a plain click (On / Off)
const DUAL_HOLD_MS = 500;
let dualWait = null, dualSkipClick = false;
const dualCancel = () => { if (dualWait) { clearTimeout(dualWait); dualWait = null; } };
$('#ws').addEventListener('pointerdown', ev => {
  if (editing || ev.button !== 0) return;     // the right button is for Help, it never presses a push button
  if (ev.target.closest('.el .svBox')) return;      // the SV box is typed in, never a press
  const n = ev.target.closest('.el, .vpPart[data-dev], .mfValve[data-dev]'); const e = n && elByName(n.dataset.name || n.dataset.dev);
  if (e && tapAction(e) === 'dual' && can('operator')) {
    dualCancel(); dualSkipClick = false;
    const name = e.tapTarget || e.name;
    dualWait = setTimeout(() => {
      dualWait = null; dualSkipClick = true; release();
      const send = () => api('POST', '/ui/hold', { name, down: true }).catch(x => { toast(x.message, true); release(); });
      held = { name, n, t: setInterval(send, 500) }; n.classList.add('pressed'); send();
    }, DUAL_HOLD_MS);
    return;
  }
  if (!e || tapAction(e) !== 'hold') return;
  if (!can('operator')) return toast('Your account is view only', true);
  ev.preventDefault(); release();
  const name = e.tapTarget || e.name;
  const send = () => api('POST', '/ui/hold', { name, down: true }).catch(x => { toast(x.message, true); release(); });
  held = { name, n, t: setInterval(send, 500) }; n.classList.add('pressed'); send();
  n.setPointerCapture?.(ev.pointerId);
});
for (const t of ['pointerup', 'pointercancel', 'blur']) window.addEventListener(t, () => { dualCancel(); release(); });
document.addEventListener('visibilitychange', () => { if (document.hidden) release(); });
$('#ws').addEventListener('contextmenu', ev => { if (!editing && ev.target.closest('.el.k-pushbutton')) ev.preventDefault(); });

// A Hose Bib set to Push Button (Panel Update Final 3 #4, OakBarn Brewery, 2026-11-18: "You could have manual valve that uses both the
// Toggle and Push Button"; Rule 18.49): open only while it is held down on its Tab, closed again when it is let go
let mvHeld = null;
const mvHoldGfx = id => { const g = S.config.graphics.find(x => x.id === id); return g && isTapMv(g) && g.mvTap === 'hold' ? g : null; };
const mvHoldSet = (g, open) => api('POST', '/ui/set', { name: g.name, prop: 'state', value: open }).then(() => setMvOpen(g.name, open)).catch(x => toast(x.message, true));
$('#ws').addEventListener('pointerdown', ev => {
  if (editing || ev.button !== 0) return;
  const n = ev.target.closest('.gfx.ip[data-fit="manualValve"]'), g = n && mvHoldGfx(n.dataset.gid); if (!g) return;
  if (!can('operator')) return toast('Only an operator or an admin can open or close a valve', true);
  if (!g.name) return toast('Save the layout once (Edit layout > Save layout) so this Manual Valve gets its name', true);
  ev.preventDefault(); mvHeld = g; mvHoldSet(g, true);
});
for (const t of ['pointerup', 'pointercancel', 'blur']) window.addEventListener(t, () => { if (mvHeld) { const g = mvHeld; mvHeld = null; mvHoldSet(g, false); } });
$('#ws').addEventListener('click', ev => {
  if (editing) return;
  if (dualSkipClick) { dualSkipClick = false; return; }       // a Dual Action held as a Push Button: its let go is not a click
  const mv = ev.target.closest('.gfx.ip[data-fit="manualValve"]');
  if (mv) return mvHoldGfx(mv.dataset.gid) ? undefined : toggleManualValve(mv.dataset.gid);      // a Push Button works on press and let go
  const mfv = ev.target.closest('.mfValve');
  if (mfv) return isPushHeld(mfv.dataset.dev) ? undefined : toggleMfValve(mfv.dataset.dev);       // a valve of a Valve Tee or Supply Manifold (Rule 5.35); a Push Button works on press

  { const o = ev.target.closest('.gfx.ovr'); if (o) return pressOverride({ id: o.dataset.gid }); }
  { const sb = ev.target.closest('.el .svBox'); if (sb) return svEdit(sb); }      // a Heating Element's SV box: type a new one (Panel Updates 40)
  // a Heating Element built into a Vessel Device: one click on its picture turns it ON or OFF at once in the method it is in, like a
  // Pump (Fritz, 2026-11-08: "Have the Graphic toggle on Off like a Pump", Rule 2.33); its box (tile) opens its pop-up
  const hp = ev.target.closest('.vpPart.vp-element[data-dev]');
  if (hp) {
    const he = elByName(hp.dataset.dev); if (!he) return;
    if (isPushHeld(he.name)) return;       // Push Button: works on press and let go (Rule 2.46)
    if (!can('operator')) return toast('Your account is view only', true);
    const k = heatMethodKey(S.values[he.name]?.method) ?? startMethod(he);
    if (!S.values[he.name]?.state && NEEDS_PROBE.includes(k) && !he.input) return toast(`${he.label || he.name}: ${heatMethodWord(k)} needs a Temperature Probe (pick one in its Properties)`, true);
    return setProp(he.name, 'state', !S.values[he.name]?.state);
  }
  const n = ev.target.closest('.el'); if (!n || ev.target.closest('.btns')) return;
  const mc = n.dataset.gid && L().graphics.find(g => g.id === n.dataset.gid && isMethodClone(g));
  if (mc) return methodCloneTap(mc);
  const e = elByName(n.dataset.name); if (e) doTap(e);
});

// A Manual Valve Widget is app-only (no PLC). One click on it opens or closes it (Fritz, 2026-10-28), at any time: it is the
// only way its .state changes. The Brain keeps it in the layout, so every screen sees it.
const toggleManualValve = guard(async id => {
  const g = S.config.graphics.find(x => x.id === id); if (!g) return;
  if (!can('operator')) throw new Error('Only an operator or an admin can open or close a valve');
  if (!g.name) throw new Error('Save the layout once (Edit layout > Save layout) so this Manual Valve gets its name');
  const open = !mvOpen(g);
  // .confirmation (on to start, Rule 1.28): "When Manually Clicked, The Popup Confirmation will still Pop Up"
  if (isConfirmation(g) && !(await byHandAsk(g.label || g.name, byHandWords(g, open)))) return;
  await api('POST', '/ui/set', { name: g.name, prop: 'state', value: open });
  setMvOpen(g.name, open); toast(`${g.label || g.name} is ${open ? 'open' : 'closed'}`);
});
// A Confirmation Widget clicked on its Tab (OakBarn Brewery, 2026-11-08, Rule 1.28: "When Manually Clicked, The Popup Confirmation will
// still Pop Up"): the pop-up asks the person to do it by hand; Done shows it On or Off (and lets a Process waiting on it go on),
// Cancel leaves it as it was.
function byHandAsk(label, { say, is }) {
  return choose(`✋ ${say} ${label} by hand, then press Done`, [[`✔ Done: it is ${is}`, true]]).then(r => r === true);
}
async function confirmByHand(t, on) {
  if (!(await byHandAsk(S.values[t.name]?.label || t.label || t.name, byHandWords(t, on)))) return;
  await setProp(t.name, 'state', on);
}
// a Manual Valve opened or closed (here or on another screen): the layout, the edit copy and the Tab follow
function setMvOpen(name, open) {
  for (const gs of [S.config.graphics, draft?.graphics]) for (const g of gs || []) if (isMv(g) && g.name === name) g.open = !!open;
  // a name such as __proto__ never reaches the Object prototype (code scanning: prototype-polluting assignment)
  if (name !== '__proto__' && name !== 'constructor' && name !== 'prototype') (S.values[name] ??= {}).state = !!open;
  const g = L().graphics.find(x => isMv(x) && x.name === name);
  if (g && g.workspace === curWs()?.name && view === 'workspace') { const n = $(`#ws .gfx[data-gid="${CSS.escape(g.id)}"]`); if (n) n.replaceWith(buildIp(g)); renderPipes(); }
}

// Big touch-friendly dialogs
// A Skynet notice (not the browser's plain box): a title, plain text and one button, Acknowledge unless told otherwise. Esc does
// not close it; the button does. Resolves when it is pressed.
function noticeDialog(title, text, button = 'Acknowledge') {
  return new Promise(res => {
    const d = $('#valDlg'); d.innerHTML = '';
    const ok = h('button', { type: 'button', class: 'big primary', onclick: () => { d.close(); res(true); } }, button);
    d.append(h('div', { class: 'vdTitle' }, title), h('div', { class: 'vdText', style: 'white-space:pre-line;max-width:440px;margin:8px 0 12px' }, text), h('div', { class: 'vdBtns' }, ok));
    d.oncancel = e => e.preventDefault();
    d.showModal(); ok.focus();
  });
}
function choose(title, buttons, current) {
  return new Promise(res => {
    const d = $('#valDlg'); d.innerHTML = '';
    const close = v => { d.close(); res(v); };
    const tt = h('div', { class: 'vdTitle' }); setRich(tt, title);
    d.append(tt,
      h('div', { class: 'vdBtns' }, ...buttons.map(([label, val]) => h('button', { type: 'button', class: 'big' + (val === current ? ' cur' : '') + (val === true ? ' onb' : val === false ? ' offb' : ''), onclick: () => close(val) }, label))),
      h('div', { class: 'vdBtns' }, h('button', { type: 'button', class: 'big', onclick: () => close(undefined) }, 'Cancel')));
    d.oncancel = () => res(undefined);
    d.showModal();
  });
}

// main setting of each control element, shown with an Enabled switch in its dialog
const CONTROL_MAIN = { pwmOut: ['value', 'Output %'], dutyCycle: ['dutycycle', 'Duty cycle %'], hysteresis: ['target', 'Setpoint'], pid: ['target', 'Setpoint'], deadband: ['target', 'Setpoint'] };
function controlDialog(t) {
  const v = S.values[t.name] || {};
  const [prop, label] = CONTROL_MAIN[t.type];
  const d = $('#valDlg'); d.innerHTML = '';
  const inp = h('input', { class: 'vdInput', value: fmtVal({}, v[prop]), inputmode: 'decimal' });
  const bump = k => { inp.value = String(+((parseFloat(inp.value) || 0) + k).toFixed(4)); };
  const done = async en => {
    const x = parseFloat(inp.value);
    if (!Number.isFinite(x)) return toast('Enter a number', true);
    d.close();
    await setProp(t.name, prop, x);
    if (en !== undefined) await setProp(t.name, 'enabled', en);
  };
  d.append(h('div', { class: 'vdTitle' }, `${v.label ?? t.name} - ${label}` + (['pid', 'deadband'].includes(t.type) ? ` (output ${fmtVal({ precision: 1 }, v.value)} %)` : '')),
    h('div', { class: 'vdRow' }, h('button', { type: 'button', class: 'big', onclick: () => bump(-1) }, '−'), inp, h('button', { type: 'button', class: 'big', onclick: () => bump(1) }, '+')),
    h('div', { class: 'vdBtns' },
      h('button', { type: 'button', class: 'big onb' + (v.enabled ? ' cur' : ''), onclick: () => done(true) }, 'Set + ON'),
      h('button', { type: 'button', class: 'big offb' + (!v.enabled ? ' cur' : ''), onclick: () => done(false) }, 'OFF'),
      h('button', { type: 'button', class: 'big primary', onclick: () => done() }, 'Set')),
    h('div', { class: 'vdBtns' }, h('button', { type: 'button', class: 'big', onclick: () => d.close() }, 'Cancel')));
  d.showModal(); setTimeout(() => { inp.focus(); inp.select(); }, 50);
}

// A Heating Element's pop-up while running (Fritz, 2026-11-07: "select the heating method via process or on the Device when
// clicked", Rule 6.19). One button per heating method (the one in use is marked), the main setting of that method with - and +
// (Duty cycle % or Target), then Set + ON, OFF, Set and Cancel. Nothing in this pop-up turns on until Set + ON or ON is clicked;
// a click on the Element itself turns it ON or OFF at once (Rule 2.33). Hysteresis, PID, Deadband and Precise need a Temperature Probe (Properties), so they are greyed out without one.
// A gas burner's pop-up (Rule 6.33): its Flame Out state and the Pause button, for opening the lid, adding cold water or doughing in.
// It watches again by itself after the Pause minutes; ▶ Watch now ends the pause early.
function flamePopRow(t, v, d) {
  if (!isGasBurner(t)) return [];
  const s = flameSettings(t), left = Number(v.flameout_paused) || 0, on = String(v.flameout ?? (s.on ? 'On' : 'Off')).toLowerCase() === 'on';
  const said = v.flameout_tripped ? '🔥 Flame Out shut the gas: check the flame, light it, then turn it ON.' : !on ? 'Flame Out: Off' : left > 0 ? `Flame Out: paused, ${left} min left` : 'Flame Out: watching';
  return [h('div', { class: 'muted' }, said), h('div', { class: 'muted' }, '⚠ Flame Out: ' + NOT_UL),
    h('div', { class: 'vdBtns' }, on ? (left > 0
      ? h('button', { type: 'button', class: 'big', title: 'Flame Out watches this burner again now', onclick: async () => { d.close(); await setProp(t.name, 'flameout_paused', 0); } }, '▶ Watch now')
      : h('button', { type: 'button', class: 'big', title: `Stops the Flame Out watch for ${s.flamePause} minutes (open the lid, add cold water, dough in). It watches again by itself after them.`, onclick: async () => { d.close(); await setProp(t.name, 'flameout', `pause ${s.flamePause}`); } }, `⏸ Pause Flame Out (${s.flamePause} min)`)) : null)];
}
function heatDialog(t) {
  const title = S.values[t.name]?.label ?? t.name, d = $('#valDlg');
  const v = { ...(S.values[t.name] || {}) };
  let m = heatMethodKey(v.method) ?? startMethod(t);
  const draw = () => {
    d.innerHTML = '';
    const main = HEAT_MAIN[m];
    // a Setpoint in the Units (Rule 2.59): typed back into its probe's units; the same number as shown changes nothing
    const own = probeOf(t)?.units, to = showUnits(), turn = main?.[0] === 'target' && needsTurn(own, to);
    const shown0 = turn && typeof v.target === 'number' ? fmtVal({ precision: 1 }, tShow(v.target, own, to)) : fmtVal({}, main ? v[main[0]] : '');
    const inp = main ? h('input', { class: 'vdInput', value: shown0, inputmode: 'decimal', 'aria-label': main[1] + (main[0] === 'target' && own ? ` (${unitShown(own, to)})` : '') }) : null;
    const bump = k => { inp.value = String(+((parseFloat(inp.value) || 0) + k).toFixed(4)); };
    const done = async on => {
      let x;
      if (inp) { x = parseFloat(inp.value); if (!Number.isFinite(x)) return toast('Enter a number', true); }
      if (turn) x = inp.value.trim() === shown0 && typeof v.target === 'number' ? v.target : tBack(x, own, to);
      d.close();
      if (heatMethodKey(v.method) !== m) await setProp(t.name, 'method', heatMethodWord(m));
      if (inp) await setProp(t.name, main[0], x);
      if (on !== undefined) await setProp(t.name, 'state', on);
    };
    const now = heatMethodKey(v.method) ?? 'onoff';
    const btn = ([k, word]) => {
      const off = NEEDS_PROBE.includes(k) && !t.input;
      // one click on a method switches to it at once (Fritz, 2026-11-07: "One Click on the dispayed device"); the pop-up stays open
      // for its setting. To Direct while ON turns it OFF first (Rule 6.19).
      return h('button', { type: 'button', class: 'big' + (k === m ? ' cur primary' : ''), ...(off ? { disabled: true, title: 'Needs a Temperature Probe: pick one in its Properties' } : {}),
        onclick: async () => { if (k === m) return; m = k; await setProp(t.name, 'method', heatMethodWord(k)); Object.assign(v, S.values[t.name] || {}); v.method = heatMethodWord(k); if (k === 'onoff') v.state = false; draw(); } }, word);
    };
    d.append(h('div', { class: 'vdTitle' }, `${title}: ${v.state ? 'ON' : 'OFF'}, ${heatMethodWord(now)}` + (v.state && PERCENT_METHODS.includes(now) ? ` (output ${fmtVal({ precision: 1 }, v.value)} %)` : '')),
      h('div', { class: 'muted' }, 'Heating method'),
      h('div', { class: 'vdBtns heatMethods' }, ...HEAT_METHODS.filter(([k]) => allowedMethods(t).includes(k) || k === now).map(btn)),
      ...(main ? [h('div', { class: 'muted' }, main[1]), h('div', { class: 'vdRow' }, h('button', { type: 'button', class: 'big', onclick: () => bump(-1) }, '−'), inp, h('button', { type: 'button', class: 'big', onclick: () => bump(1) }, '+'))] : []),
      h('div', { class: 'muted' }, m === 'onoff' ? 'Switching to Direct turns it OFF first; click ON for full power.' : 'A click on a method switches to it at once.'),
      ...flamePopRow(t, v, d),
      h('div', { class: 'vdBtns' },
        h('button', { type: 'button', class: 'big onb' + (v.state ? ' cur' : ''), onclick: () => done(true) }, main ? 'Set + ON' : 'ON'),
        h('button', { type: 'button', class: 'big offb' + (!v.state ? ' cur' : ''), onclick: () => done(false) }, 'OFF'),
        h('button', { type: 'button', class: 'big primary', onclick: () => done() }, 'Set')),
      h('div', { class: 'vdBtns' }, h('button', { type: 'button', class: 'big', onclick: () => d.close() }, 'Cancel')));
    if (inp) inp.addEventListener('keydown', ke => { if (ke.key === 'Enter') { ke.preventDefault(); done(); } });
  };
  draw();
  d.showModal();
}

// ---- The SetPoint pop-up (Fritz, 2026-11-08: "Click on a Thermowell or Probe or Display of a Temperature NOT in edit Mode, Bring
// up SetPoint Dialog", Rule 2.43, Help 160). A click on a Temperature Probe, a Thermowell, a Probe built into a Vessel, or a
// picture or Dial that shows one opens the SetPoint of the Heating Element that holds that temperature (the one whose Temperature
// Probe it is; older Hysteresis, PID and Deadband Devices too). Two or more: it asks which. None: it says so (a simulated probe
// still opens its Simulated reading pop-up).
const SP_OLD = ['hysteresis', 'pid', 'deadband'];
const SP_METHODS = ['hysteresis', 'pid', 'deadband', 'precise'];      // the heating methods that hold a Setpoint (Target)
function heatersOf(probe, first) {
  const out = [], add = e => { if (e && !out.includes(e) && (isHeatElem(e) || SP_OLD.includes(e.type))) out.push(e); };
  if (first) add(elByName(first));
  // a Fermentor Control that reads this probe holds it (Rule 6.30): its Setpoint, not its heater's (the Fermentor runs its heater)
  const ferm = S.config.elements.filter(e => isFermentor(e) && e.input === probe.name);
  if (ferm.length) return ferm;
  for (const e of S.config.elements) if (e.input === probe.name) add(e);
  return out;
}
async function probeTap(p, first) {
  if (!can('operator')) return toast('Your account is view only', true);
  const pl = S.values[p.name]?.label ?? p.label ?? p.name, hs = heatersOf(p, first);
  if (!hs.length) {
    if (simDev(p.device) && !p.sim) return valueDialog(p);
    return toast(`${pl}: no Heating Element holds this temperature. Pick this probe as the Temperature Probe in a Heating Element's Properties.`, true, 6000);
  }
  const t = hs.length === 1 ? hs[0] : await choose(`${pl}: whose Setpoint?`, hs.map(e => [S.values[e.name]?.label ?? e.label ?? e.name, e]));
  if (t) setpointDialog(p, t);
}
// a Probe built into a Vessel Device, or a Vessel's own Probe spot (its Probe, the Vessel's Heater first): not a tile, so a click
// listener of its own (Rule 2.43)
$('#ws').addEventListener('click', ev => {
  if (editing) return;
  const vp = ev.target.closest('.vpPart.vp-probe[data-dev], .vpPart.vp-thermowell[data-dev]');
  if (vp) { const p = elByName(vp.dataset.dev); if (p) probeTap(p); return; }
  const vw = ev.target.closest('.gfx.vessel .vwProbe, .gfx.vessel .twell:not(.elmark)');
  if (vw) { const g = L().graphics.find(x => x.id === vw.closest('.gfx')?.dataset.gid), p = g?.probe && elByName(g.probe); if (p) probeTap(p, g.heater); }
});
function setpointDialog(p, t) {
  const d = $('#valDlg'); d.innerHTML = '';
  const pv = S.values[p.name] || {}, v = S.values[t.name] || {}, he = isHeatElem(t);
  const tl = v.label ?? t.label ?? t.name, pl = pv.label ?? p.label ?? p.name, u = p.units || '°F';
  const onNow = he || isFermentor(t) ? !!v.state : !!v.enabled;
  const now = he ? (heatMethodKey(v.method) ?? startMethod(t)) : t.type;
  // the method it uses for the Setpoint: the one in use if it holds a Setpoint, else the first allowed one that does
  const m = !he ? t.type : SP_METHODS.includes(now) ? now : allowedMethods(t).find(k => SP_METHODS.includes(k));
  // in the Units (Rule 2.59): shown to 0.1 when the probe keeps the other units; typed back into the probe's units, and the same number
  // as shown changes nothing
  const to = showUnits(), turn = needsTurn(u, to), kept = typeof v.target === 'number' ? v.target : typeof t.target === 'number' ? t.target : null;
  const shown0 = kept !== null ? (turn ? fmtVal({ precision: 1 }, tShow(kept, u, to)) : fmtVal({}, kept)) : fmtVal({}, Math.round((turn ? tShow(pv.value ?? 0, u, to) : pv.value) ?? 0));
  const inp = h('input', { class: 'vdInput', value: shown0, inputmode: 'decimal', 'aria-label': `Setpoint (${unitShown(u, to)})` });
  const bump = k => { inp.value = String(+((parseFloat(inp.value) || 0) + k).toFixed(4)); };
  const done = async on => {
    const x0 = parseFloat(inp.value); if (!Number.isFinite(x0)) return toast('Enter a number', true);
    const x = !turn ? x0 : kept !== null && inp.value.trim() === shown0 ? kept : tBack(x0, u, to);
    d.close();
    if (he && m && m !== now) await setProp(t.name, 'method', heatMethodWord(m));
    await setProp(t.name, 'target', x);
    if (on !== undefined) await setProp(t.name, he || isFermentor(t) ? 'state' : 'enabled', on);
  };
  const reading = pv.fault ? 'FAULT' : tempTxt(p, pv.value, u);
  const word = he ? heatMethodWord(now) : isFermentor(t) ? `Fermentor, ${v.mode ?? 'Heat & Cool'}, ${v.doing ?? 'Off'}` : { hysteresis: 'Hysteresis', pid: 'PID', deadband: 'Deadband' }[t.type];
  const note = !m ? `${tl} has no heating method that holds a Setpoint. Tick Hysteresis, PID, Deadband or Precise in its Properties.`
    : he && m !== now ? `${tl} is on ${heatMethodWord(now)} now. Set switches it to ${heatMethodWord(m)}.` : '';
  d.append(h('div', { class: 'vdTitle' }, `${pl}: ${reading}`),
    h('div', { class: 'muted' }, `Setpoint of ${tl} (${onNow ? 'ON' : 'OFF'}, ${word})`),
    ...(m ? [h('div', { class: 'vdRow' }, h('button', { type: 'button', class: 'big', onclick: () => bump(-1) }, '−'), inp, h('button', { type: 'button', class: 'big', onclick: () => bump(1) }, '+'))] : []),
    ...(note ? [h('div', { class: 'muted' }, note)] : []),
    ...(m ? [h('div', { class: 'vdBtns' },
      h('button', { type: 'button', class: 'big onb' + (onNow ? ' cur' : ''), title: 'Sets the Setpoint and turns it ON', onclick: () => done(true) }, 'Set + ON'),
      h('button', { type: 'button', class: 'big offb' + (!onNow ? ' cur' : ''), title: 'Sets the Setpoint and turns it OFF', onclick: () => done(false) }, 'OFF'),
      h('button', { type: 'button', class: 'big primary', title: 'Sets the Setpoint; ON or OFF stays as it is', onclick: () => done() }, 'Set'))] : []),
    h('div', { class: 'vdBtns' },
      ...(he ? [h('button', { type: 'button', class: 'big', title: 'Opens the Heating Element pop-up: its heating method, Duty cycle and ON / OFF', onclick: () => { d.close(); heatDialog(t); } }, 'Heating method…')] : []),
      ...(simDev(p.device) && !p.sim ? [h('button', { type: 'button', class: 'big', title: 'Simulator: sets what this probe reads', onclick: () => { d.close(); valueDialog(p); } }, 'Simulated reading…')] : []),
      h('button', { type: 'button', class: 'big', onclick: () => d.close() }, 'Cancel')));
  inp.addEventListener('keydown', ke => { if (ke.key === 'Enter') { ke.preventDefault(); done(); } });
  d.showModal(); if (m) setTimeout(() => { inp.focus(); inp.select(); }, 50);
}

// ---- Process Widget (OakBarn Brewery, 2026-11-09, Rule 1.31, public/processwidget.js, Help 173) ----
// Its Label is the title; under it what its Process is doing (Running, Waiting, Stopped, Stopped on an error) and a Start / Stop
// button. The whole Widget is the button: one click starts the Process when it is stopped and stops it when it runs, with no pop-up
// (Rule 2.44). An item set to Ask before changing asks first. What it shows comes from the Processes list, so it follows every change.
const processStatusOf = name => (S.scripts || []).find(x => x.name === String(name ?? '').trim()) ?? null;
function fillProcessWidget(n, e) {
  const st = { ...processState(e.process, processStatusOf(e.process)) }, vl = n.querySelector('.vl');
  // a Group (Panel Update 9, item 12): while the delay timer runs every one shows Delay, the pressed one's button says Started and the
  // others' Start is greyed out; once the water flows the pressed one shows Running (word and button) and the others go blank, still
  // greyed out, until the Group is free again
  const gv = S.values[e.name] || {}, busy = !!(String(e.group ?? '').trim() && gv.phase), mine = busy && !!gv.pressed;
  if (busy) { st.word = gv.phase === 'delay' ? 'Delay' : mine ? 'Running' : ''; st.running = false; }
  n.classList.toggle('grpBusy', busy);
  n.classList.add('procw');
  n.classList.toggle('scr-error', !!st.error); n.classList.toggle('scr-missing', !!st.missing);
  const pic = processPicture(e, turnsOn);
  if (vl) vl.replaceChildren(...(pic ? [h('div', { class: 'procPic', style: `background-image: url("${media(pic)}")` })] : []), h('div', { class: 'scrState' }, st.word), h('div', { class: 'scrBtn' + (st.running ? ' stop' : '') + (busy && !mine ? ' grey' : '') + (mine ? ' pressed' : '') }, st.missing ? '' : mine ? (gv.phase === 'delay' ? 'Started' : 'Running') : processButton(st)));
  n.title = st.missing ? `${e.label || e.name}: ${st.word}. Pick its Process in its Properties (double-click it).` : busy ? `${e.label || e.name}: wait until the ${e.group} buttons are free again.` : `Process ${e.process}: ${st.word}. One click ${st.running ? 'stops' : 'starts'} it.`;
  return st.running;
}
async function processWidgetTap(e) {
  const name = String(e.process ?? '').trim();
  const st = processState(name, processStatusOf(name));
  if (st.missing) return toast(`${e.label || e.name}: ${st.word}. Double-click it to pick its Process.`, true);
  if (String(e.group ?? '').trim() && S.values[e.name]?.phase) return;      // its Group is busy: the greyed Start does nothing (Panel Update 9)
  if (e.confirm && !(await choose(`${st.running ? 'Stop' : 'Start'} Process ${name}?`, [[st.running ? safetyWord('Stop') : 'Start', true]]))) return;
  try {
    const r = await api('POST', `/ui/scripts/${encodeURIComponent(name)}/${st.running ? 'stop' : 'start'}${!st.running && String(e.group ?? '').trim() ? '?widget=' + encodeURIComponent(e.name) : ''}`);
    if (!st.running && !r.ok) toast(r.msg ? `${name}: ${r.msg}` : `${name} did not start`, true);
  } catch (x) { toast(x.message, true); }
}
// the Processes list changed (one started, stopped, was renamed ...): every Process Widget on the screen shows it
function refreshProcessWidgets() {
  for (const n of document.querySelectorAll('#ws .el.procw')) { const e = elNamed(n.dataset.name); if (e) fillEl(n, e); }
}

// Manual vessel widget (BrewZilla, DigiBoil and other appliances with their own controller): no board pin.
// A script says what to set by hand (setpoint, heat, pump, timer, message) and waits for the brewer to confirm here.
function fillManual(n, e, v) {
  if (isAppliance(e.appliance)) return fillAppliance(n, e, v);
  const u = e.units || '°F', rows = n.querySelector('.mvRows'), pic = n.querySelector('.mvPic');
  const img = (v.heat ? (e.imageOn || e.image) : (e.imageOff || e.image)) || '';
  pic.style.backgroundImage = img ? `url("${media(img)}")` : '';
  pic.classList.toggle('hidden', !img);
  const row = (k, val, cls = '') => h('div', { class: 'mvRow ' + cls }, h('span', {}, k), h('b', {}, val));
  rows.innerHTML = '';
  rows.append(row('Set to', `${fmtVal({ precision: e.precision ?? 0 }, v.setpoint)} ${u}`),
    row('Heat', v.heat ? 'ON' : 'OFF', v.heat ? 'hot' : ''),
    ...(e.noPump ? [] : [row('Pump', v.pump ? 'ON' : 'OFF', v.pump ? 'run' : '')]),
    ...(v.timer && v.timer !== '00:00:00' ? [row('Timer', v.timer)] : []),
    ...(v.reading ? [row('Reads', `${fmtVal({ precision: 1 }, v.reading)} ${u}`)] : []),
    ...(v.volume ? [row('Volume', `${fmtVal({ precision: 2 }, v.volume)} ${e.volumeUnits || 'gal'}`)] : []));
  n.classList.toggle('waiting', !!v.waiting);
}
// The Controls of a DigiBoil or 65 L Brewzilla (Fritz, 2026-11-07, Rule 5.39): each of its switches, its screen (set point, what it
// reads, the Brewzilla's On/Off button and its ▶ Run spot) and its valves, the way they were last set by hand. A set point in °F shows
// its °C too: the screen goes back to °C every time it is turned off.
const avValves = e => { const g = L().graphics.find(x => x.id === e.integratedIn); return g ? (APPLIANCES[e.appliance]?.valves || []).map(([k, words]) => [L().elements.find(x => x.integratedIn === g.id && x.integratedAs === 'av:' + k), words]).filter(([x]) => x) : []; };
function fillAppliance(n, e, v) {
  const a = APPLIANCES[e.appliance], u = e.units || '°F', rows = n.querySelector('.mvRows'), pic = n.querySelector('.mvPic');
  pic.classList.add('hidden');      // the vessel beside it is the picture
  const row = (k, val, cls = '') => h('div', { class: 'mvRow ' + cls }, h('span', {}, k), h('b', {}, val));
  const onOff = (k, run) => v[k] ? 'ON' : 'OFF';
  rows.innerHTML = '';
  rows.append(...((e.label || e.name) === a.name ? [] : [h('div', { class: 'mvRow mvHead' }, h('b', {}, a.name))]),
    ...a.switches.map(([k, words]) => row(words.replace(/ switch$/, ''), onOff(k), v[k] ? (k === 'pump' ? 'run' : 'hot') : '')),
    ...(a.screen.onOff ? [row('Screen', onOff('power'), v.power ? 'run' : '')] : []),
    row('Set point', v.setpoint ? setpointWords(v.setpoint, u) : 'not set'),
    ...(v.reading ? [row('Screen reads', `${fmtVal({ precision: 1 }, v.reading)} ${u}`)] : []),
    ...avValves(e).map(([x, words]) => row(words.replace(/ \(.*$/, ''), isOn(x.name) ? 'OPEN' : 'CLOSED', isOn(x.name) ? 'run' : '')),
    ...(a.screen.run ? [h('button', { type: 'button', class: 'mvRun' + (v.run ? ' on' : ''), title: `The Run spot on the ${a.name} screen: click when you have pressed Run on the real one (Rule 5.39)`,
      onpointerdown: ev => ev.stopPropagation(), ondblclick: ev => ev.stopPropagation(),
      onclick: ev => { ev.stopPropagation(); if (editing || !can('operator')) return; setProp(e.name, 'run', !v.run); } }, v.run ? '■ Running: press Run to stop' : '▶ Run')] : []));
  n.classList.toggle('waiting', (S.valves || []).some(q => q.ask && q.process && q.label && q.label.includes(e.label || e.name)));
}
// a click on its Controls in run mode: say what you set by hand (Skynet can't see it)
async function applianceDialog(t) {
  const a = APPLIANCES[t.appliance], v = S.values[t.name] || {}, lbl = v.label ?? t.label ?? t.name, title = lbl === a.name ? lbl : `${lbl} (${a.name})`, u = t.units || '°F';
  const r = await choose(title + ': what did you set by hand?', [
    ...a.switches.map(([k, words]) => [`${words}: turned ${v[k] ? 'OFF' : 'ON'}`, 'sw:' + k]),
    ...(a.screen.onOff ? [[`Screen On/Off button: turned ${v.power ? 'OFF' : 'ON'}`, 'sw:power']] : []),
    ...(a.screen.run ? [[v.run ? 'Pressed Run to stop it' : 'Pressed Run', 'sw:run']] : []),
    ...avValves(t).map(([x, words]) => [`${words.replace(/ \(.*$/, '')}: ${isOn(x.name) ? 'closed' : 'opened'}`, 'mv:' + x.name]),
    [`Set point: changed (${u})`, 'setpoint'], ['Enter the temperature its screen shows', 'reading']]);
  if (!r) return;
  if (r.startsWith('sw:')) { const k = r.slice(3); return setProp(t.name, k, !v[k]); }
  if (r.startsWith('mv:')) { const x = r.slice(3); return setProp(x, 'state', !isOn(x)); }
  const x = parseFloat(prompt(r === 'setpoint' ? `New set point of the ${title} in ${u}${/c/i.test(u.replace(/[^A-Za-z]/g, '')) ? '' : ' (its screen may show °C: type the °F number here)'}:`
    : `Temperature on the ${title} screen (${u}):`, '') || '');
  if (Number.isFinite(x)) { await setProp(t.name, r, x); if (r === 'setpoint') toast(`${title}: set point ${setpointWords(x, u)}`); }
}
async function manualDialog(t) {
  if (isAppliance(t.appliance)) return applianceDialog(t);
  const v = S.values[t.name] || {}, title = v.label ?? t.name;
  const r = await choose(v.waiting ? `${title}: ${v.message || 'confirm when done'}` : title,
    [...(v.waiting ? [['Done ✓', 'ok']] : []), ['Enter the temperature it shows', 'reading'], ['Enter the volume in it', 'volume']]);
  if (r === 'ok') { await setProp(t.name, 'confirmed', true); return setProp(t.name, 'waiting', false); }
  if (r === 'reading' || r === 'volume') {
    const x = parseFloat(prompt(r === 'reading' ? `Temperature on the ${title} display (${t.units || '°F'}):` : `Volume in the ${title} (${t.volumeUnits || 'gal'}):`, '') || '');
    if (Number.isFinite(x)) setProp(t.name, r, x);
  }
}

function valueDialog(t) {
  if (CONTROL_MAIN[t.type]) return controlDialog(t);
  const v = S.values[t.name] || {};
  const title = v.label ?? t.name;
  if (t.type === 'scale') return scaleDialog(t, title);
  if (t.type === 'stepper') return stepperDialog(t, title);
  if (t.type === 'digitalIn') {   // latch / toggle: reset to off; counter: count back to 0
    const sim = !simDev(t.device) ? [] : t.mode === 'momentary' ? [['Simulate: press', 'press']] : [['Simulate: input ON', 'on'], ['Simulate: input OFF', 'off']];
    return choose(title, [...sim, ['counter', 'momentary'].includes(t.mode) ? ['Reset count to 0', 'count'] : ['Reset (off)', 'reset']])
      .then(async r => r === 'press' ? (await setProp(t.name, 'raw', true), setProp(t.name, 'raw', false)) : r === 'count' ? setProp(t.name, 'count', 0) : r === 'reset' ? setProp(t.name, 'reset', true) : r ? setProp(t.name, 'raw', r === 'on') : undefined);
  }
  if (isBoolEl(t)) return choose(title, [['ON', true], ['OFF', false]], isOn(t.name)).then(r => r !== undefined && setProp(t.name, boolProp(t), r));
  const numDev = ['pwmOut', 'analogOut', 'analogIn', 'temperature'].includes(t.type);
  if (!(isVarEl(t) || numDev || isDataW(t)) || t.readOnly) return;
  if (numDev) t = { ...t, dataType: 'value', units: t.type === 'pwmOut' ? '%' : t.units,
    min: t.type === 'pwmOut' ? 0 : t.type === 'analogOut' ? (t.rangeLow ?? 0) : t.min, max: t.type === 'pwmOut' ? 100 : t.type === 'analogOut' ? (t.rangeHigh ?? 100) : t.max };
  const d = $('#valDlg'); d.innerHTML = '';
  if (isDataW(t)) t = { ...t, dataType: dataWDt(t) };
  const num = t.dataType === 'value', k = vkKind(t);
  const inp = t.dataType === 'string' && k !== 'graphic'
    ? h('textarea', { class: 'vdInput', rows: k === 'longstring' ? 12 : 3 }, v.value ?? '')
    : h('input', { class: 'vdInput', value: num ? fmtVal(t, v.value) : (v.value ?? ''), inputmode: num ? 'decimal' : 'text', placeholder: { time: 'hh:mm:ss', datetime: 'mm/dd/yyyy hh:mm:ss' }[t.dataType] ?? (k === 'graphic' ? 'image path, e.g. Images/Skynet/Other_Equipment/BurnerFlame.png' : '') });
  const step = +t.step || 1;
  const bump = k => { const x = (parseFloat(inp.value) || 0) + k * step; inp.value = t.precision !== undefined && t.precision !== '' ? x.toFixed(+t.precision) : String(+x.toFixed(6)); };
  const done = ok => {
    if (ok) {
      let val = inp.value;
      if (num) { const x = parseFloat(val); if (!Number.isFinite(x)) return toast('Enter a number', true); if (t.min !== undefined && x < t.min) return toast(`Lowest is ${t.min}`, true); if (t.max !== undefined && x > t.max) return toast(`Highest is ${t.max}`, true); val = x; }
      setProp(t.name, 'value', val);
    }
    d.close();
  };
  d.append(h('div', { class: 'vdTitle' }, title + (t.units ? ` (${t.units})` : '')),
    k === 'longstring' && v.file ? h('div', { class: 'muted' }, 'Saved to ' + v.file) : '',
    num ? h('div', { class: 'vdRow' }, h('button', { type: 'button', class: 'big', onclick: () => bump(-1) }, '−'), inp, h('button', { type: 'button', class: 'big', onclick: () => bump(1) }, '+')) : inp,
    h('div', { class: 'vdBtns' }, h('button', { type: 'button', class: 'big', onclick: () => done(false) }, 'Cancel'), h('button', { type: 'button', class: 'big primary', onclick: () => done(true) }, 'Set')));
  inp.addEventListener('keydown', ke => { if (ke.key === 'Enter' && inp.tagName === 'INPUT') { ke.preventDefault(); done(true); } });
  d.showModal(); setTimeout(() => { inp.focus(); inp.select?.(); }, 50);
}

// Timer: Set button. Hours : minutes : seconds in three boxes (00:00:00), keeps running or stopped as it was
function timerSetDialog(t) {
  const v = S.values[t.name] || {};
  const cur = String(v.value ?? '00:00:00').split(':').map(x => parseInt(x, 10) || 0);
  while (cur.length < 3) cur.unshift(0);
  const d = $('#valDlg'); d.innerHTML = '';
  const box = (val, label) => h('label', { class: 'tmBox' }, h('input', { class: 'vdInput', value: String(val).padStart(2, '0'), inputmode: 'numeric', 'aria-label': label,
    onfocus: ev => ev.target.select() }), h('span', { class: 'muted' }, label));
  const hh = box(cur[0], 'hours'), mm = box(cur[1], 'minutes'), ss = box(cur[2], 'seconds');
  const ins = [hh, mm, ss].map(b => b.querySelector('input'));
  const done = ok => {
    if (ok) {
      const [H, M, Sx] = ins.map(i => i.value.trim() === '' ? 0 : Number(i.value.trim()));
      if (![H, M, Sx].every(x => Number.isInteger(x) && x >= 0)) return toast('Use whole numbers, for example 01:30:00', true);
      if (M > 59 || Sx > 59) return toast('Minutes and seconds go up to 59', true);
      setProp(t.name, 'value', [H, M, Sx].map(x => String(x).padStart(2, '0')).join(':'));
    }
    d.close();
  };
  // typing or pasting a whole time like 1:30:00 into any box fills all three
  for (const i of ins) i.addEventListener('input', () => {
    const m = /^(\d+):(\d{1,2})(?::(\d{1,2}))?$/.exec(i.value.trim());
    if (m) { const parts = m[3] === undefined ? [0, m[1], m[2]] : [m[1], m[2], m[3]]; ins.forEach((x, k) => { x.value = String(parts[k]).padStart(2, '0'); }); }
  });
  for (const i of ins) i.addEventListener('keydown', ke => { if (ke.key === 'Enter') { ke.preventDefault(); done(true); } });
  d.append(h('div', { class: 'vdTitle' }, `${v.label ?? t.name} - set time`),
    h('div', { class: 'vdRow tmRow' }, hh, h('b', {}, ':'), mm, h('b', {}, ':'), ss),
    h('div', { class: 'muted' }, v.running ? 'It keeps running from the new time.' : ((v.type ?? t.timerType) === 'countdown' ? 'Counts down from this time when started.' : 'Counts up from this time when started.')),
    h('div', { class: 'vdBtns' }, h('button', { type: 'button', class: 'big', onclick: () => done(false) }, 'Cancel'), h('button', { type: 'button', class: 'big primary', onclick: () => done(true) }, 'Set')));
  d.showModal(); setTimeout(() => { ins[0].focus(); ins[0].select(); }, 50);
}

// Scale: Tare (zero it now) or calibrate with a known weight
async function scaleDialog(t, title) {
  const r = await choose(title, [['Tare (zero)', 'tare'], ['Calibrate…', 'cal']]);
  if (r === 'tare') return setProp(t.name, 'tare', true);
  if (r === 'cal') {
    const w = parseFloat(prompt(`1. Tare the empty scale first.\n2. Put a known weight on it.\n3. Enter that weight in ${t.weightUnits || 'lb'}:`) || '');
    if (w > 0) { await setProp(t.name, 'calibrate', w); toast('Scale calibrated'); }
  }
}

// Stepper: move it from the screen (the same properties a Process sets)
async function stepperDialog(t, title) {
  const v = S.values[t.name] || {}, u = STEP_UNITS[t.units]?.[0] ?? t.units ?? '', lim = [t.minPos, t.maxPos].some(x => x !== undefined && x !== '') ? `  (allowed ${t.minPos ?? '…'} to ${t.maxPos ?? '…'})` : '';
  const hasHome = t.homePin !== undefined && t.homePin !== '';
  const r = await choose(`${title}: at ${fmtVal(t, v.position)} ${u}`, [
    ['Move to …', 'target'], ['Move by …', 'move'], ['Turn at a speed …', 'run'], ['Stop', 'stop'],
    ...(hasHome ? [['Home (find the switch)', 'home']] : []), ['Call this position home', 'reset'],
    v.enabled === false ? ['Turn the motor on', 'on'] : ['Turn the motor off (free to turn by hand)', 'off']]);
  if (!r) return;
  if (['stop', 'home', 'reset'].includes(r)) return setProp(t.name, r, true);
  if (r === 'on' || r === 'off') return setProp(t.name, 'enabled', r === 'on');
  const ask = { target: `Go to which position (${u})?${lim}`, move: `Move by how much (${u}, minus = backward)?`, run: `Turn at how many ${u} per second (minus = backward, 0 = stop)?` }[r];
  const x = parseFloat(prompt(ask, r === 'target' ? fmtVal(t, v.target) : '') ?? '');
  if (Number.isFinite(x)) setProp(t.name, r, x);
}

