  Long_Branch: { label: 'Long Tee, probe in the branch', img: 'Images/Skynet/Other_Equipment/Skynet_TC15_Long_Tee_Probe_Branch.svg', size: [160, 102], ends: [[0, 29 / 134], [1, 29 / 134]], bend: [0.5, 29 / 134] },     // Fritz's drawing 2026-11-04
