// Stepper dropdowns: the built-in list, anything already used on another stepper, and "Add new ..."
function stepperPick(key, list, v) {
  const num = list !== 'driver' && list !== 'units', items = [...STEP_LISTS[list]];
  for (const e of (draft || S.config).elements) if (e.type === 'stepper' && e[key] !== undefined && e[key] !== '' && !items.some(([x]) => String(x) === String(e[key]))) items.push([e[key], String(e[key])]);
  if (v !== undefined && v !== '' && !items.some(([x]) => String(x) === String(v))) items.push([v, String(v)]);
  const s = h('select', { 'data-k': key, 'data-kind': 'stpick', ...(num ? { 'data-num': '1' } : {}) }, h('option', { value: '' }, '(pick one)'),
    ...items.map(([x, l]) => h('option', { value: x, ...(String(x) === String(v ?? '') ? { selected: true } : {}) }, l)), h('option', { value: '__add__' }, 'Add new ...'));
  addNewFirst(s);
  let prev = s.value;
  s.addEventListener('change', () => {
    if (s.value === '__add__') {
      const t = (prompt({ driver: 'Driver board name (for example TMC5160)', stepsPerRev: 'Motor steps per turn (a number, for example 100)', microsteps: 'Microsteps (a number, for example 10)', units: 'Unit name (for example oz)' }[list]) || '').trim();
      if (!t || (num && !(+t > 0))) { s.value = prev; if (t) toast('Enter a number above 0', true); return; }
      if (![...s.options].some(o => o.value === t)) s.insertBefore(h('option', { value: t }, t), s.lastChild);
      s.value = t;
    }
    prev = s.value;
    const d = list === 'driver' && STEP_DRIVERS[s.value];
    if (d) for (const [k, x] of Object.entries(d)) {      // fill in that driver's usual settings
      const f = $(`#dlgBody [data-k="${k}"]`); if (!f) continue;
      if (f.tagName === 'SELECT' && ![...f.options].some(o => o.value === String(x))) f.insertBefore(h('option', { value: x }, String(x)), f.lastChild);
      f.value = String(x); if (k === 'wiring') f.dispatchEvent(new Event('change', { bubbles: true }));
    }
  });
  return s;
}

// backpath_2 / _3 changed: a heads-up that one picture path is enough in Skynet (Fritz, 2026-10-27; renamed 2026-11-02).
// The heads-up can be turned off with its tick box.
const HEADSUP_KEY = 'skynet.backpathHeadsUpOff';
function backpathHeadsUp() {
  try { if (localStorage.getItem(HEADSUP_KEY)) return; } catch { }
  let d = $('#pathHeadsUpDlg');
  if (!d) {
    const off = h('input', { type: 'checkbox' });
    d = h('dialog', { id: 'pathHeadsUpDlg' }, h('h3', {}, 'Heads up: one picture path is all you need'),
      h('p', {}, '.backpath_2 and .backpath_3 hold background pictures 2 and 3: .background = 1, 2 or 3 picks .backpath, .backpath_2 or .backpath_3 (0, blank or over 3 = no background), and a Process can change them too.'),
      h('p', {}, h('b', {}, 'In Skynet, any Device or Widget can have as many pictures as you like'), ' with the .image attribute. It puts the new path in .backpath and shows it at once (.background = 1):'),
      h('pre', { class: 'mono' }, 'my_widget.image = "Images/RedPump.png"'),
      h('p', {}, 'For on / off, the preferred way is one picture plus an On overlay (see its Properties).'),
      h('p', { class: 'muted' }, 'More in Help > Pictures on items.'),
      h('label', { class: 'check' }, off, ' Do not show this again'),
      h('div', { class: 'bar' }, h('span', { class: 'spacer' }), h('button', { class: 'primary', onclick: () => { if (off.checked) try { localStorage.setItem(HEADSUP_KEY, '1'); } catch { } d.close(); } }, '✔ OK')));
    document.body.append(d);
  }
  d.showModal();
}

function readFields(obj, root = $('#dlgBody')) {
  for (const inp of [...root.querySelectorAll('[data-k]'), ...(root.id === 'dlgBody' ? $$('#dlgTitle [data-k]') : [])]) {
    const k = inp.dataset.k, kind = inp.dataset.kind;
    let v;
    if (kind === 'bool') v = inp.checked;
    else if (kind === 'vis') v = inp.checked ? undefined : 'hidden';
    else if (kind === 'show') v = inp.checked ? undefined : true;
    else if (kind === 'pairs') { v = pairsFrom(inp.value); if (!v.length) v = undefined; }
    else if (kind === 'calchain') {
      v = [...inp.querySelectorAll('.calRow')].map(box => {
        const c = { type: box.querySelector('.calType').value };
        if (!box.querySelector('.calOn').checked) c.enabled = false;
        for (const n of box.querySelectorAll('.calNum')) { if (n.value === '' || !Number.isFinite(+n.value)) throw new Error(`${CAL_KINDS[c.type]?.[0] ?? c.type}: type a number in every box`); c[n.dataset.f] = +n.value; }
        const rows = box.querySelector('.calRows'); if (rows) { c.rows = pairsFrom(rows.value); if (!c.rows.length) throw new Error('Lookup Table: write at least one pair, a reading and its value'); }
        return c;
      });
      if (!v.length) v = undefined;
    }
    else if (kind === 'vkitems') {
      v = [...inp.querySelectorAll('.vkrow')].map(tr => ({ value: tr.querySelector('.vkv').value.trim(), text: tr.querySelector('.vkt').value.trim() })).filter(r => r.value !== '' || r.text);
      for (const r of v) { if (r.value === '' || !Number.isFinite(+r.value)) throw new Error(`Choice "${r.text}": its Value must be a number`); r.value = +r.value; }
      if (new Set(v.map(r => r.value)).size !== v.length) throw new Error('Two choices have the same Value');
    }
    else if (kind === 'num' || kind === 'numsel') {
      v = inp.value === '' ? undefined : +inp.value;
      if (v !== undefined && inp.dataset.tk) v = inp.dataset.tk === 'q' ? qBoxBack(v, inp.dataset.shown, inp.dataset.kept, inp.dataset.own, showUnits(), inp.dataset.as) : boxBack(inp.dataset.tk, v, inp.dataset.shown, inp.dataset.kept, inp.dataset.own, showUnits());      // typed in the Units, saved in the probe's (Rule 2.59)
    }
    else if (kind === 'owpick') {      // a 1-Wire Index: circuit_index (Rule 6.37), kept as the probe's number and its circuit
      const m = /^(\d+)_(\d+)$/.exec(inp.value), ck = k === 'probeIndex' ? 'owCircuit' : k + 'Circuit';
      if (m) obj[ck] = +m[1]; else delete obj[ck];
      v = m ? +m[2] : undefined;
    }
    else if (kind === 'bgsel') v = inp.value === '' ? undefined : /^-?\d+$/.test(inp.value) ? +inp.value : inp.value;
    else if (kind === 'pin') { const t = inp.value.trim().toUpperCase(); v = t === '' ? undefined : /^\d+$/.test(t) ? +t : t; }
    else if (kind === 'yn') v = inp.value === 'yes';
    else if (kind === 'stpick') v = inp.value === '' || inp.value === '__add__' ? undefined : inp.dataset.num ? +inp.value : inp.value;
    else if (kind === 'multi') v = [...inp.selectedOptions].map(o => o.value);
    else if (kind === 'ticks') { v = [...inp.querySelectorAll('input.tick:checked')].map(c => c.value); if (!v.length) v = undefined; }
    else if (kind === 'dbgroups') { v = JSON.parse(inp.dataset.groups || '[]'); if (!v.length) v = undefined; }
    else if (kind === 'json') { if (inp.value.trim() === '') v = undefined; else { try { v = JSON.parse(inp.value); } catch { throw new Error(`${k}: not valid JSON`); } } }
    else v = inp.value === '' ? undefined : inp.value;
    if (v === undefined) delete obj[k]; else obj[k] = v;
  }
}

// A form of fields in a box (a dialog, or a Menu tab): "Add new ..." in a list and selects that change the fields are handled here.
// onChange runs after any change. Returns build(), which draws the fields again.
// Open / closed (on / off) pictures come in pairs (Fritz, 2026-10-22): picking one fills in its partner when a picture with the
// matching name exists, e.g. a user's own My_Valve_Closed.svg -> My_Valve_Open.svg (Skynet's valves have no Open pictures since
// 2026-11-05: an Overlay shows open). The orientation is the user's pick.
const PIC_PAIR = { imageOff: 'imageOn', imageOn: 'imageOff', imageClosed: 'imageOpen', imageOpen: 'imageClosed' };
const picPartner = p => { const swap = { Closed: 'Open', Open: 'Closed', closed: 'open', open: 'closed', Off: 'On', On: 'Off', off: 'on', on: 'off' };
  const file = p.split('/').pop(), m = file.match(/(Closed|Open|Off|On|(?<![A-Za-z])(?:closed|open|off|on))(?=[^a-z]|$)/);
  return m ? p.slice(0, p.length - file.length) + file.slice(0, m.index) + swap[m[1]] + file.slice(m.index + m[1].length) : null; };
function fillPicPair(body, sel) {
  const other = body.querySelector(`select[data-k="${PIC_PAIR[sel.dataset.k]}"][data-kind="gpick"]`), p = picPartner(sel.value);
  if (!other || !p || p === sel.value || !vList(other.dataset.list || 'onoff').concat(mediaPics).includes(p)) return;
  if (![...other.options].some(o => o.value === p)) other.insertBefore(h('option', { value: p }, p), other.lastChild);
  other.value = p; other.dispatchEvent(new Event('change'));      // shows its preview (does not bubble back here)
}
// Rule 2.38 (Fritz, 2026-11-06: "Dialogs should be kept as clean as possible ... Hover on all Dialogs"): before a dialog is drawn,
// its explanations move into hover help, for every dialog at once (Rule 18.10's exception):
//  - a note that explains goes into the tip of the field after it (or before it, at the end); notes at the top with no field
//    near them go into the hover help of the dialog's title;
//  - a long explanation in ( ) after a field's name ("Read only (a tap does nothing; a Process sets it)") becomes its tip;
//  - what stays: warnings (⚠), what something is now (Suggested Name, OPEN / CLOSED), short headings, and a dialog that is only
//    a message (no fields to fill in).
const INPUT_KINDS = f => Array.isArray(f) && !['note', 'head', 'box', 'boxend', 'infonote', 'attrhead'].includes(f[2]) && !!f[1] && !f[6]?.inTitle;
const KEEP_NOTE = t => /^\s*(⚠|🧪|Suggested|It is (OPEN|CLOSED)|Kind:|Name:|Clone of)/.test(t) || (t.length < 40 && !/\.\s*$/.test(t));
const withTip = (f, tip) => { const g = [...f]; while (g.length < 6) g.push(g.length === 3 ? null : false); const x = g[6] || {}; g[6] = { ...x, tip: x.tip ? x.tip + ' ' + tip : tip }; return g; };
// Titles and field names in Title Case (OakBarn Brewery, 2026-11-10: "Titles and Attribute Labels follow Pascal Camel Code Style"):
// each plain lower-case word gets its capital, the small joining words stay small (not the first), and what is in ( ) is left as
// it is. Only names (up to 5 words): a long sentence is an explanation, which belongs in its balloon (Rule 11.8).
const TITLE_SMALL = new Set(['a', 'an', 'and', 'as', 'at', 'but', 'by', 'for', 'from', 'in', 'into', 'of', 'on', 'or', 'per', 'the', 'to', 'vs', 'via', 'with']);
