    if (e.type === 'alarm' && !a._endHook) { a._endHook = true; a.addEventListener('ended', () => { if (!a.loop && S.values[e.name]?.active) api('POST', '/ui/sound/finished', { name: e.name }).catch(() => { }); }); }
