for (const id of ['#simWatch', '#simLead', '#simReach', '#simReachAfter']) $(id).addEventListener('change', () => { simDirty = true; });
$('#simAddJump').onclick = () => { simDraft.push({ on: true, when: 'timer', name: '', after: 5, jump: '00:50:00', note: '' }); simDirty = true; renderSimJumps(); };
const simMoreOpen = open => { $('#simMore').classList.toggle('hidden', !open); $('#simMoreBtn').setAttribute('aria-expanded', String(open)); if (open) renderSimSettings(); };
$('#simMoreBtn').onclick = () => simMoreOpen($('#simMore').classList.contains('hidden'));
$('#simMoreClose').onclick = () => simMoreOpen(false);
$('#simSave').onclick = $('#simSave2').onclick = guard(async () => {
  for (const j of simDraft) if (!/^\d+:\d{1,2}(:\d{1,2})?$/.test(j.jump || '')) throw new Error(`"${j.jump}" is not a time. Write it as hh:mm:ss, for example 00:50:00`);
  S.sim = await api('PUT', '/ui/sim', { lead: +$('#simLead').value, watch: +$('#simWatch').value, reachWaits: $('#simReach').checked, reachAfter: +$('#simReachAfter').value, jumps: simDraft });
  simDirty = false; await load(); savedPop('Simulator settings saved');
});
// Simulator or Real boards, for the whole panel (every Interface at once): the 🔌 Real / 🧪 Simulator button on the Tabs bar
// (Fritz, 2026-10-27) and the ☰ Menu. Returns false when the admin said no.
async function setSimulator(on) {
  // not while brewing (OakBarn Brewery, 2026-11-23): a Flow, Sub or Repeat Process running; Loopers do not count (Rule 10.12)
  if (on && (S.scripts || []).some(x => x.state === 'running' && x.cls !== 'looper')) return toast('Not while brewing: stop the running Processes first, then switch to the Simulator', true), false;
  if (!await skyConfirm(on ? 'Switch the whole panel to the Simulator?\n\nEvery process stops and every output turns off. Then every real board is let go and the simulator takes its place, so nothing real is switched until you switch back to Real boards.\n\nTimers run as now (faster if you set a speed), and a Process that waits on a reading, like a temperature or the boil starting, moves on by itself after a while.'
    : 'Switch the whole panel to the Real boards?\n\nEvery process stops and every output turns off, then the real boards are used again. Heaters, pumps and valves will really switch.', { ok: on ? '🧪 Switch to Simulator' : '🔌 Switch to Real boards' })) return false;
  S.sim = await api('PUT', '/ui/sim', { on });
  await load(); toast(on ? '🧪 Simulator mode: no real hardware is switched. 25× speed and Auto skip are on' : '🔌 Real boards: real hardware is used');
  return true;
}
$('#barSim').onclick = guard(() => setSimulator(!S.sim?.on));

$('#tlShow').onclick = guard(async () => {
  const name = $('#tlPick').value; if (!name) throw new Error('There are no Processes yet');
  const r = await api('GET', '/ui/sim/timeline/' + encodeURIComponent(name));
  tlRows = { name, rows: r.rows };
  const tb = $('#tlBody'); tb.innerHTML = '';
  for (const x of r.rows) {
    const when = (x.after ? `${fmtT(x.at)} after line ${x.after}` : fmtT(x.at)) + (x.maybe ? ' (if)' : '');
    const what = x.what === 'wait' ? (x.unknown ? 'waits (how long is not known ahead)' : `waits ${fmtT(x.secs)}`) : x.what === 'sleep' ? `sleeps ${fmtT(x.secs)}` : '';
    tb.append(h('tr', { class: x.what === 'wait' || x.what === 'sleep' ? 'wait' : '' }, h('td', { class: x.maybe ? 'maybe' : '' }, when), h('td', {}, String(x.line)), h('td', {}, h('code', {}, x.text), what ? ' ' : '', what ? h('span', { class: 'muted' }, what) : '')));
  }
  $('.tlTable').classList.toggle('hidden', !r.rows.length);
  $('#tlNote').textContent = (r.rows.length ? `About ${fmtT(r.end.at)}${r.end.after ? ` after line ${r.end.after}` : ''} from start to finish. Steps marked (if) only happen when that "if" is true. ` : 'Nothing to show. ') + (r.note || '');
  $('#tlMake').disabled = !r.rows.some(x => !x.after && x.at > 0);
});
// Time jumps that, after the Process starts, skip to a few seconds before each timed step (chained one after the other)
$('#tlMake').onclick = () => {
  if (!tlRows) return;
  const lead = +$('#simLead').value || 5, speed = S.sim?.speed || 1;
  const times = [...new Set(tlRows.rows.filter(x => !x.after && x.at > 0 && x.what !== 'sleep' && x.what !== 'wait').map(x => x.at))].sort((a, b) => a - b);
  simDraft = simDraft.filter(j => !(j.when === 'process' && j.name === tlRows.name));
  let real = 5, jumped = 0, made = 0;
  for (const at of times) {
    const jump = Math.round(at - lead - real * speed - jumped);
    if (jump < 10) continue;                         // so close it is not worth a jump
    const step = tlRows.rows.find(x => x.at === at && !x.after);
    simDraft.push({ on: true, when: 'process', name: tlRows.name, after: real, jump: fmtT(jump), note: `to ${fmtT(at - lead)}: line ${step.line}` });
    jumped += jump; made++;
    real += Math.ceil(lead / speed) + 5;             // time to watch that step happen
  }
  simDirty = true; renderSimJumps();
  toast(made ? `${made} time jump${made > 1 ? 's' : ''} added. Check them, then press Save.` : 'Every step is only seconds apart: no jumps needed');
};

// ---------------------------------------------------------------- Schemas (the dropdown at the top)
