  const btn = h('button', { type: 'button', class: 'menuBtn', title: 'Menu: Edit layout, the Menu tabs and the pages', 'aria-haspopup': 'true', 'aria-expanded': 'false' });
  btn.innerHTML = MENU_SVG + label;
