// else Default settings); a change here is the Recipe's own. The Whirlpool hops on the Hops tab each pick a stand.
function rcHopStandsRow(rc, u, changed) {
  const stands = hopStands(rc, null, S.boilProfiles.find(x => x.id === rc.boilProfile)), op = can('operator');
  const keep = (key, obj) => () => { rc.hopStands = { ...(rc.hopStands || {}), [key]: { tempC: obj.tempC, min: obj.min } }; changed(); };
  return h('div', { class: 'rcRow' }, ...stands.flatMap(st => {
    const o = { tempC: st.tempC, min: st.min }, k = keep(st.key, o);
    return [rcBox('r', `Hop Stand ${st.label}`, rcInput(o, 'tempC', { d: 0, to: v => cTo(v, u.tempUnit), from: v => toC(v, u.tempUnit), ro: !op, onChange: k }), { unit: TU(u.tempUnit), field: `skn_rcp_Hop_Stand_${st.key}_Temp`, tip: HS_TEMP_TIPS[st.key] }),
      rcBox('g', `${st.label} Minutes`, rcInput(o, 'min', { d: 0, ro: !op, onChange: k }), { unit: 'min', field: `skn_rcp_Hop_Stand_${st.key}_Minutes`, tip: HS_TIME_TIP })];
  }));
}
function rcMain(pane, rc, u, changed) {
  rc.volumes = rc.volumes || {};
  const c = { onChange: changed }, vol = { to: v => lTo(v, u.volumeUnit), from: v => toL(v, u.volumeUnit), ...c }, tmp = { d: 1, to: v => cTo(v, u.tempUnit), from: v => toC(v, u.tempUnit), ...c };
  const V = { unit: u.volumeUnit }, T = { unit: TU(u.tempUnit) };
  // Style: a dropdown with "Add new ..." (Rule: multi-way = dropdown)
  const styles = [...new Set([...RC_STYLES, ...(S.config.vesselLists?.styles || []), ...(rc.style ? [rc.style] : [])])];
  const style = rcInput(rc, 'style', { kind: 'sel', list: [['', ''], ...styles.map(s => [s, s]), ['__add__', 'Add new ...']], ...c });
  style.addEventListener('change', guard(async () => {
    if (style.value !== '__add__') return;
    const s = (prompt('New style name') || '').trim();
    rc.style = s || rcView.recipe.style || '';
    if (s && !styles.includes(s)) { const lists = S.config.vesselLists = { ...(S.config.vesselLists || {}) }; lists.styles = [...(lists.styles || []), s]; await api('PUT', '/ui/settings', { vesselLists: lists }); }
    renderMenuPane();
  }));
  const calcBox = (title, key, show, unit, tip, field) => rcBox('c', title, h('input', { type: 'text', value: show(rc[key]), disabled: true, tabIndex: -1 }), { unit, tip, field });
  const calc = guard(() => rcCalculate(rc, changed));
  pane.append(
    h('div', { class: 'rcRow' },
      rcBox('k', 'Beer Name', rcInput(rc, 'name', { kind: 'text', ...c }), { wide: true, field: 'skn_rcp_Name' }),
      rcBox('k', 'Style', style, { wide: true, field: 'skn_rcp_Style' }),
      rcBox('k', 'Brew Length', rcInput(rc.volumes, 'batchLiters', vol), { ...V, tip: 'The batch size, into the fermenter', field: 'skn_rcp_Batch_Volume' }),
      rcBox('k', 'Brew on', rcBrewOnPick(rc, changed), { wide: true, tip: BREW_ON_TIP }),
      calcBox('Grain Wt.', 'grainKg', v => rcRound(kgTo(v, u.grainUnit), 2), u.grainUnit, 'The weight of all the grains (Grain tab). Calculate works it out', 'skn_rcp_Total_Grain_Weight'),
      calcBox('1st Mash', 'firstMashC', v => rcRound(cTo(v, u.tempUnit), 1), TU(u.tempUnit), 'The first mash step (MASH tab). Calculate works it out', 'skn_rcp_First_Mash_Temp'),
      calcBox('IBU', 'ibuCalc', v => rcRound(v, 0), '', 'Bitterness from the Hops tab (Tinseth), with the Actual AAU of each hop. Calculate works it out', 'skn_rcp_IBU'),
      calcBox('Expected Gravity', 'expectedSG', v => rcRound(v, 3), '', 'The sum of the gravity points (PPG>SG) of every grain and fermentable, with the Brewhouse Efficiency of the Brew on Tab\'s Equipment Profile. Worked out when an amount changes, and by Calculate', 'skn_rcp_Expected_Gravity'),
      rcBox('b', 'Strike Volume', rcInput(rc, 'strikeLiters', vol), { ...V, field: 'skn_rcp_Strike_Volume' }),
      rcBox('r', 'Strike Temperature', rcInput(rc, 'strikeTempC', tmp), { ...T, field: 'skn_rcp_Strike_Temp' }),
      rcBox('r', 'Grain Temperature', rcInput(rc, 'grainTempC', tmp), { ...T, field: 'skn_rcp_Grain_Temp' })),
    h('div', { class: 'rcRow' },
      rcBox('b', 'Sparge Volume', rcInput(rc, 'spargeLiters', vol), { ...V, field: 'skn_rcp_Sparge_Volume' }),
      rcBox('g', 'Sparge Type', rcInput(rc, 'spargeType', { kind: 'sel', list: [['batch', 'Batch'], ['fly', 'Fly'], ['none', 'No sparge']], ...c }), { field: 'skn_rcp_Sparge_Type' }),
      rcBox('g', 'Sparge Minutes', rcInput(rc, 'spargeMinutes', { d: 0, ...c }), { unit: 'min', field: 'skn_rcp_Sparge_Minutes' }),
      rcBox('r', 'Sparge Temperature', rcInput(rc, 'spargeTempC', tmp), { ...T, field: 'skn_rcp_Sparge_Temp' }),
      rcBox('b', 'PreBoil Volume', rcInput(rc.volumes, 'boilLiters', vol), { ...V, field: 'skn_rcp_Boil_Volume' }),
      rcBox('g', 'Boil Profile', rcBoilPick(rc, changed), { wide: true, field: 'skn_rcp_Boil_Profile', tip: 'A Skynet Boil Profile, one of your own (☰ Menu > Boil Profile), or none. Picking one fills in the Boil Minutes and its Hop Stands.' }),
      rcBox('g', 'Boil Minutes', rcInput(rc, 'boilTime', { d: 0, ...c }), { unit: 'min', field: 'skn_rcp_Boil_Minutes', tip: '0 = No Boil. Each kit has its own boil time (some are No Boil): read the kit. A Can Kit starts at 0' }),
      rcBox('g', 'Whirlpool Minutes', rcInput(rc, 'whirlpoolMinutes', { d: 0, ...c }), { unit: 'min', field: 'skn_rcp_Whirlpool_Minutes' }),
      rcBox('r', 'Pitch At', rcInput(rc, 'pitchTempC', { ...tmp, d: 0 }), { ...T, field: 'skn_rcp_Pitch_Temp' }),
      rcBox('g', `Grain Ratio/${u.ratioUnit === 'qt/lb' ? 'Qt' : 'L'}`, rcInput(rc, 'waterToGrain', { to: v => ratioTo(v, u.ratioUnit), from: v => toRatio(v, u.ratioUnit), ...c }), { unit: u.ratioUnit, field: 'skn_rcp_Grain_Ratio' }),
      can('operator') ? h('button', { class: 'rcCalcBtn', onclick: calc, title: 'Works out the Total Grain Weight, Hop Drops, Warnings and Messages, 1st Mash Temperature, IBU, and the Strike and Sparge Volume and Temperature' }, 'Calculate') : ''),
    rcHopStandsRow(rc, u, changed),
    h('div', { class: 'rcNote' }, h('b', {}, 'Most Fields can be edited.'),
      ...[['Grain Wt.', 'skn_rcp_Total_Grain_Weight'], ['1st Mash', 'skn_rcp_First_Mash_Temp'], ['IBU', 'skn_rcp_IBU'], ['Expected Gravity', 'skn_rcp_Expected_Gravity']].filter(([, f]) => levelShowsBox(rc, f)).map(([t]) => h('span', { class: 'rcMini' }, t)),
      h('b', {}, 'These fields are calculated from the Other Tabs.')),
    h('div', { class: 'rcLower' },
      h('div', { class: 'rcDaughters' }, ...RC_DAUGHTERS.filter(([k]) => levelShowsTab(rc, k)).map(([k, t, about]) => h('div', { class: 'rcDRow' },
        h('button', { class: 'rcTabBtn', onclick: () => { rcSub = k; renderMenuPane(); }, title: `Opens the ${t} tab` }, t), h('span', {}, about)))),
      // the CLICK Here and Calculate legend is gone (Panel Update 9, item 33c: "Clutter. Get Rid of it"): the buttons say it in their Hover Help
    ),
    h('p', { class: 'muted' }, `${rc.name ? `"${rc.name}": ` : ''}${rcFrom(rc)}${rc.sourceFile ? `, ${rc.sourceFile}` : ''}${rc.importedAt ? `, imported ${new Date(rc.importedAt).toLocaleString()}` : ''}. Amounts show in the units picked on ☰ Menu > Default.`));
  // the boxes this Recipe Level does not use are not shown (Rule 17.11); their values stay in the Recipe
  for (const el of pane.querySelectorAll('.rcBox[data-field]')) if (!levelShowsBox(rc, el.dataset.field)) el.remove();
}
// Calculate (the Recipe tab and the Hops tab): only when every hop has an Actual AAU above zero. Otherwise nothing is
// changed and a warning says which hops to fix or delete (Fritz's Hops tab, 2026-10-31).
// When one is 0, Skynet switches to the Hops tab, highlights the Actual AAU boxes that are 0 and shows Fritz's warning.
let rcAAWarn = false;
async function rcCalculate(rc, changed) {
  const bad = levelShowsTab(rc, 'hops') ? hopActualProblems(rc) : [];     // a Level 1 Can Kit has no HOPs tab: its hops are not checked
  if (bad.length) {
    // the hops to fix are named (Panel Update 9, item 26); the tab goes to the first one (Boil Hops or Pre and Post Boil Hops)
    rcAAWarn = true; const first = rc.ingredients.hops[bad[0].line - 1]; rcSub = first && !isBoilHop(first) ? 'posthops' : 'hops'; renderMenuPane();
    return readWarning('Actual AAU', ['Any Hop MUST have its Actual AAU set to the AAU on the Hop Package. The Recipe is based on a Recipe AAU, but the real IBUs of a Brew is calculated using the Actual AAU.',
      `Update the Actual AAU of: ${bad.map(x => `Hop ${x.line} (${x.name})`).join(', ')}. Then try Calculate again.`, 'Click the Read Button to exit this dialog.']);
  }
  rcAAWarn = false;
  sortHops(rc);
  Object.assign(rc, calculateRecipe(rc, S.config.brewDefaults || {}, rcMashProfile(rc), undefined, rcEff(rc), rcStrikeOff(rc))); changed();
  // Calculate also saves (Panel Update 9, item 27: "No need to save button. Do it when it calculates")
  if (can('operator')) { await api('PUT', '/ui/recipe', rcWork); await rcLoad(); }
  renderMenuPane();
  toast('Calculated and saved');
}
// a warning that has one button, READ, to close it
function readWarning(title, lines) {
  const d = h('dialog', { class: 'readWarn' }, h('h3', {}, '⚠ ' + title), ...lines.map(t => h('p', {}, t)),
    h('div', { class: 'bar' }, h('button', { class: 'primary', onclick: () => d.close() }, 'READ')));
  d.onclose = () => d.remove(); document.body.append(d); d.showModal();
}
// a true/false switch (Rule: true/false = switch)
function rcSwitch(on, onChange, title = '') {
  const box = h('input', { type: 'checkbox', ...(on ? { checked: true } : {}) });
  box.onchange = () => onChange(box.checked);
  return h('label', { class: 'sw', title }, box, h('span', { class: 'swk' }));
}

// ---- The Hops tab (Fritz's layout, 2026-10-31) and the Pre and Post Boil Hops tab (Panel Update 9, items 22 to 27). One line for each hop,
// no limit. The Hops tab holds the Boil Hops: the title of each line is its Hop Group, colored (Bitter above 20 minutes orange, Flavor
// above 5 up to 20 yellow, Aroma 5 or less green), its Drop shows as a time (75 = 01:15:00), and the square box sends it to the Post
// Boil Hops tab. The Pre and Post Boil Hops tab holds every other hop (Mash, 1st WORT, Secondary, DRY, Whirlpool): its switches and boxes change
// the hop at once (one click, no Save or Cancel of their own), a DRY or Secondary hop shows its Pull Date (its date plus its Days), and
// a hop whose switches are all turned off goes back to the Hops tab. Calculate (top right on both) checks every Actual AAU, works out
// the Recipe and saves it. Every box is a Skynet_Field (skn_rcp_Hop_N_...). The lines are put in order on Calculate and on Save.
const RC_HOP_SW = [['mash', 'Mash Hops'], ['first wort', '1st WORT Hops'], ['secondary', 'Secondary Hops'], ['dry hop', 'DRY Hops'], ['whirlpool', 'Whirlpool']];
const rcHopOpen = new WeakSet();      // hops sent to the Pre and Post Boil Hops tab whose switch is not picked yet (they are still Boil Hops)
const isBoilHop = hop => hop.use === 'boil' || !HOP_USES[hop.use];
// the boxes every hop line has (name, amount, unit, Recipe and Actual AAU, Calc amount), on both tabs
function rcHopCommon(rc, hop, i, u, c, title, titleColor) {
  const op = can('operator'), F = end => hopFieldName(i + 1, end), wt = hopUnitOf(hop, u);
  const wName = w => w === 'oz' ? 'Ounces' : 'Grams';
  const ms = rcInput({ unit: wt }, 'unit', { kind: 'sel', list: Object.entries(HOP_MEASURES), ro: !op, onChange: () => {} });
  ms.addEventListener('change', () => { hop.unit = ms.value; c.onChange(); renderMenuPane(); });
  const calc = h('input', { type: 'text', disabled: true, tabIndex: -1 });
  const actual = rcBox('r', 'Actual', rcInput(hop, 'alphaActual', { d: 1, onChange: () => { actual.classList.toggle('hopZero', rcAAWarn && !(+hop.alphaActual > 0)); c.onChange(); } }),
    { field: F('AA_Actual'), tip: 'The AAU % on the package of the hops on hand. It must be above 0 before Calculate' });
  actual.classList.toggle('hopZero', rcAAWarn && hopActualProblems({ ingredients: { hops: [hop] } }).length > 0);
  const name = rcBox('k', title, rcInput(hop, 'name', { kind: 'text', ...c }), { wide: true, field: F('Name'), tip: `Hop ${i + 1}` });
  if (titleColor) { const hd = name.querySelector('.rcBoxHead'); hd.style.background = titleColor; hd.style.color = '#111'; }
  return { calc, boxes: [name,
    rcBox('g', wName(wt), rcInput(hop, 'kg', { d: wt === 'g' ? 1 : 2, to: v => kgTo(v, wt), from: v => toKg(v, wt), ...c }), { field: F('Amount'), tip: 'The amount in the recipe' }),
    rcBox('g', 'Unit', ms, { field: F('Measurement'), tip: 'This hop line\'s own unit, oz or g, whatever Units says. Changing it turns the amount' }),
    rcBox('g', 'Recipe', rcInput(hop, 'alpha', { d: 1, ...c }), { field: F('AA_Recipe'), tip: 'AAU % of the hop in the recipe' }),
    actual,
    rcBox('c', `Calc ${wt === 'oz' ? 'Oz' : 'g'}`, calc, { field: F('Calc_Amount'), tip: 'The amount to use with the Actual AAU, to get the IBUs of the recipe' })] };
}
// the head of both tabs: its title, Add, oz → g, and Calculate on the top right (Panel Update 9, item 22)
function rcHopHead(pane, rc, u, changed, title, add) {
  const op = can('operator'), hops = rc.ingredients.hops;
  const ozLines = hops.filter(x => hopUnitOf(x, u) === 'oz');
  const toGrams = guard(() => { for (const x of ozLines) x.unit = 'g'; changed(); renderMenuPane(); toast(`${ozLines.length} hop line${ozLines.length === 1 ? '' : 's'} now in grams. Press Save to keep it`); });
  pane.append(h('div', { class: 'hopHead' }, h('h2', {}, title), op && add ? h('button', { class: 'hopAdd', onclick: add, title: 'Add a hop line at the bottom' }, 'Add Hop ', h('b', {}, '+')) : '',
    op && ozLines.length ? h('button', { onclick: toGrams, title: 'Turns every hop line in ounces into grams. Grams are more accurate, and some scales start in grams' }, 'oz → g') : '',
    h('span', { class: 'hopAAU' }, 'AAU %'), h('span', { class: 'spacer' }),
    op ? h('button', { class: 'rcCalcBtn', onclick: guard(() => rcCalculate(rc, changed)), title: 'Checks the Actual AAU of every hop (Boil, Pre and Post Boil), puts the hop lines in order, works out the Calc amounts and the whole Recipe, and saves it' }, 'Calculate') : ''));
}
const rcHopDelBtn = (rc, i, changed) => h('button', { class: 'hopDel', onclick: guard(() => { const hops = rc.ingredients.hops; if (!confirm(`Delete Hop ${i + 1}${hops[i].name ? ` (${hops[i].name})` : ''}?`)) return; hops.splice(i, 1); changed(); renderMenuPane(); }), title: `Delete Hop ${i + 1}` }, '🗑 Delete');
function rcHops(pane, rc, u, changed) {
  const hops = rc.ingredients.hops, D = S.config.brewDefaults || {}, op = can('operator');
  const rows = [];
  // the boxes worked out from the others: Calc oz, Drop, IBU. Typing in a box updates them all.
  const refresh = () => {
    const boil = +rc.boilTime || 60;
    rows.forEach(({ hop, calc, drop, ibu }) => {
      calc.value = rcRound(kgTo(hopKgToUse(hop), hopUnitOf(hop, u)), 2);
      drop.value = minutesHms(Math.max(0, boil - Math.min(+hop.time || 0, boil)));
      ibu.value = rcRound(hopIbu(rc, hop), 1);
    });
  };
  const c = { onChange: () => { changed(); refresh(); } };
  const F = (i, end) => hopFieldName(i + 1, end);
  const add = guard(() => { hops.push({ name: '', kg: null, unit: u.hopUnit, alpha: null, alphaActual: 0, use: 'boil', time: null, dryDays: null, date: '', wpTempC: null, hopRocket: false }); changed(); renderMenuPane(); });
  rcHopHead(pane, rc, u, changed, 'Hops', add);
  const boilHops = hops.map((hop, i) => [hop, i]).filter(([hop]) => isBoilHop(hop) && !rcHopOpen.has(hop));
  if (!boilHops.length) pane.append(h('p', { class: 'muted' }, hops.length ? 'No Boil Hops: every hop is on the Pre and Post Boil Hops tab.' : 'No hops yet. Press Add Hop, or IMPORT a recipe on the Recipe tab.'));
  for (const [hop, i] of boilHops) {
    const grp = HOP_GROUPS[hopGroupOf(hop.time)];
    const { calc, boxes } = rcHopCommon(rc, hop, i, u, c, grp.title, grp.color);
    const r = { hop, i, calc, drop: h('input', { type: 'text', disabled: true, tabIndex: -1 }), ibu: h('input', { type: 'text', disabled: true, tabIndex: -1 }) };
    const sq = h('input', { type: 'checkbox', class: 'hopSq', title: 'Send it to the Pre and Post Boil Hops tab (Mash, 1st Wort, Secondary, Dry Hop or Whirlpool)' });
    sq.onchange = () => { rcHopOpen.add(hop); rcSub = 'posthops'; renderMenuPane(); };
    const line = h('div', { class: 'rcRow hopLine' }, ...boxes, h('div', { class: 'hopSqBox' }, sq),
      rcBox('g', `Hop ${i + 1} Min`, rcInput(hop, 'time', { d: 0, onChange: () => { c.onChange(); renderMenuPane(); } }), { field: F(i, 'Min'), tip: `Boil minutes. ${rc.boilTime || 60} (the Boil Time) = a Start of Boil hop. Above 20 = Bitter, above 5 = Flavor, 5 or less = Aroma` }),
      rcBox('c', `Hop ${i + 1} Drop`, r.drop, { field: F(i, 'Drop'), tip: 'How far into the boil it goes in (hh:mm:ss)' }),
      rcBox('c', `Hop ${i + 1} IBU`, r.ibu, { field: F(i, 'IBU') }),
      op ? rcHopDelBtn(rc, i, changed) : '');
    rows.push(r); pane.append(line);
  }
  refresh();
  pane.append(h('p', { class: 'muted' }, `${boilHops.length} Boil Hop${boilHops.length === 1 ? '' : 's'}, IBU ${rcRound(rc.ibuCalc, 0) || '?'} (last Calculate). They are grouped by drop time: a Start of Boil hop (Min = Boil Time) first, then by Minutes. The square box sends a hop to the Pre and Post Boil Hops tab. The hop order and the alerts are on the Drops tab (${hopSchedule(rc, D).alerts.length} alerts).`));
}
// ---- The Pre and Post Boil Hops tab (Panel Update 9, items 23 and 25): every hop that is not a Boil Hop, and the ones just sent here
function rcPostHops(pane, rc, u, changed) {
  const hops = rc.ingredients.hops, op = can('operator');
  const rows = [];
  const refresh = () => rows.forEach(({ hop, calc }) => { calc.value = rcRound(kgTo(hopKgToUse(hop), hopUnitOf(hop, u)), 2); });
  const c = { onChange: () => { changed(); refresh(); } };
  rcHopHead(pane, rc, u, changed, 'Pre and Post Boil Hops', null);
  const list = hops.map((hop, i) => [hop, i]).filter(([hop]) => !isBoilHop(hop) || rcHopOpen.has(hop));
  if (!list.length) pane.append(h('p', { class: 'muted' }, 'No Pre and Post Boil Hops. On the Hops tab, the square box of a hop sends it here.'));
  for (const [hop, i] of list) {
    const { calc, boxes } = rcHopCommon(rc, hop, i, u, c, `Hop ${i + 1}`);
    rows.push({ hop, calc });
    pane.append(h('div', { class: 'rcRow hopLine' }, ...boxes, rcPostHopBox(rc, hop, i, u, changed), op ? rcHopDelBtn(rc, i, changed) : ''));
  }
  refresh();
}
// the Post Boil boxes of one hop line: they change the hop at once (no Save or Cancel, Rule 2.44's one click; Panel Update 9, item 27)
function rcPostHopBox(rc, hop, i, u, changed) {
  const box = h('div', { class: 'hopDlg' });
  const F = end => hopFieldName(i + 1, end);
  const bp = () => S.boilProfiles.find(x => x.id === rc.boilProfile);
  const use = isBoilHop(hop) ? null : hop.use;
  const set = (w, on) => {
    if (on) { hop.use = w; rcHopOpen.delete(hop); if (w === 'whirlpool' && !hop.stand) hop.stand = standOf(hop, hopStands(rc, null, bp())); }
    else { hop.use = 'boil'; rcHopOpen.delete(hop); rcSub = 'hops'; }      // every switch off: it is a Boil Hop again, back on the Hops tab
    changed(); renderMenuPane();
  };
  const sw = ([w, label]) => h('div', { class: 'hopSw' }, h('b', {}, label), rcSwitch(use === w, on => set(w, on)));
  box.append(...(use ? [sw(RC_HOP_SW.find(x => x[0] === use))] : RC_HOP_SW.map(sw)));
  if (use === 'secondary' || use === 'dry hop') {
    const what = use === 'secondary' ? 'Secondary Hop Date' : 'Dry Hop Date';
    const pull = h('input', { type: 'text', disabled: true, tabIndex: -1, value: fmtDay(pullDate(hop.date, hop.dryDays)) });
    const date = h('input', { type: 'date', value: hop.date || '' }); date.onchange = () => { hop.date = date.value; pull.value = fmtDay(pullDate(hop.date, hop.dryDays)); changed(); };
    box.append(rcBox('g', what, date, { wide: true, field: F('Date') }),
      rcBox('g', 'Days', rcInput(hop, 'dryDays', { d: 0, onChange: () => { pull.value = fmtDay(pullDate(hop.date, hop.dryDays)); changed(); } }), { field: F('Days') }),
      rcBox('c', use === 'secondary' ? 'Pull Date' : 'Dry Hop Pull Date', pull, { wide: true, tip: 'Its date plus its Days: the day to take the hops out (Calculated)' }));
  }
  // the Hop Stand it goes in at (three Hop Stands, OakBarn Brewery 2026-11-13; the Whirlpool questions, Panel Updates entry 13). The
  // stand's Temperature and Time are the Recipe's own, shared by every hop in that stand: a change here is kept in the Recipe at once
  // (so the Recipe tab's Hop Stand boxes show it; Panel Update 9, item 27: "hop stand middle did not update")
  if (use === 'whirlpool') {
    const st = hopStands(rc, null, bp()), cur = st.find(x => x.key === hop.stand);
    const o = cur ? { tempC: cur.tempC, min: cur.min } : null;
    const keepStand = () => { rc.hopStands = { ...(rc.hopStands || {}), [hop.stand]: { tempC: o.tempC, min: o.min } }; changed(); if (!standReady({ ...cur, ...o })) toast(HS_WARN, true); };
    box.append(rcBox('g', 'Hop Stand', rcInput(hop, 'stand', { kind: 'sel', list: [['', ''], ...st.map(x => [x.key, x.label])], onChange: () => { changed(); renderMenuPane(); } }), { field: F('Hop_Stand'), tip: HS_PICK_TIP }),
      ...(o ? [rcBox('r', 'Temperature', rcInput(o, 'tempC', { d: 0, to: v => cTo(v, u.tempUnit), from: v => toC(v, u.tempUnit), onChange: keepStand }), { unit: TU(u.tempUnit), field: `skn_rcp_Hop_Stand_${hop.stand}_Temp`, tip: HS_TEMP_TIPS[hop.stand] }),
        rcBox('g', 'Time', rcInput(o, 'min', { d: 0, onChange: keepStand }), { unit: 'min', field: `skn_rcp_Hop_Stand_${hop.stand}_Minutes`, tip: HS_TIME_TIP })] : []),
      rcBox('g', 'Min', rcInput(hop, 'time', { d: 0, onChange: changed }), { field: F('Min'), tip: 'How long this hop steeps in the whirlpool (used for its bitterness). The Hop Stand Time is how long the cooling water stays off.' }),
      h('div', { class: 'hopSw' }, h('b', {}, 'Hop Rocket'), rcSwitch(!!hop.hopRocket, on => { hop.hopRocket = on; changed(); }, 'Skynet_Field ' + F('Hop_Rocket'))));
  }
  return box;
}
// "2026-12-05" shown as the computer shows a date (12/05/2026 in the USA)
const fmtDay = d => d ? new Date(d + 'T12:00:00').toLocaleDateString() : '';

// ---- The Grain tab and the Fermentable tab (Fritz, 2026-10-31). One list in the Recipe (ingredients.fermentables): the
// Grain tab shows the ones of Type Grain (the Type is hidden), the Fermentable tab every other Type, with a Type dropdown.
// Boxes: name, amount, Potential (yield %), SRM (color), and After Boil, a switch shown only for the Types a brewer adds
// during or after the boil. No limit on lines. Every box is a Skynet_Field (skn_rcp_Grain_N_..., skn_rcp_Fermentable_N_...).
function rcFerms(pane, rc, u, changed, grainTab) {
  const all = rc.ingredients.fermentables, op = can('operator'), c = { onChange: changed };
  const mine = all.filter(f => isGrain(f) === grainTab), W = u.grainUnit, what = grainTab ? 'Grain' : 'Fermentable';
  // the labels come from the Default tab: the grain weight standard (skn_XML_Grain_WT_Standard) or its own label, and PPG>SG
  const D = S.config.brewDefaults || {};
  const wLabel = D.grainLabelVisible === false ? '' : grainWtLabel(D.units), pLabel = D.ppgLabel || 'PPG>SG';
  const total = h('b', {}), eg = h('b', {}), pts = [];
  // a changed amount or Potential: the gravity points of each line, the total, and the Expected Gravity on the Recipe tab
  const sum = () => {
    total.textContent = `${rcRound(kgTo(mine.reduce((a, f) => a + (+f.kg || 0), 0), W), 2)} ${W}`;
    const eff = rcEff(rc);
    // an empty PPG>SG box says what it needs (Panel Update 9, item 34: "PPG>SG did not calculate"): Rule 17.13 gives a grain no points
    // without the Brew on Tab's Brewhouse Efficiency, and every line needs the Brew Length and its Potential
    for (const [f, el] of pts) {
      el.value = rcRound(gravityPoints(f, rc, eff), 1);
      el.placeholder = el.value ? '' : !(+rc.volumes?.batchLiters > 0) ? 'Brew Length?' : f.yieldPct === null || f.yieldPct === undefined || f.yieldPct === '' ? 'Potential?' : mashedFerm(f) && !eff ? 'Brew on Tab?' : '';
    }
    rc.expectedSG = expectedGravity(rc, eff);
    rc.grainKg = recipeTotals(rc).grainKg;      // the Recipe tab's Grain Wt. follows the Grain tab at once (Panel Update 9, item 19)
    eg.textContent = rc.expectedSG ? rcRound(rc.expectedSG, 3) : !all.length ? '(no grains or fermentables yet)' : !eff && rc.ingredients?.fermentables?.some(mashedFerm) ? '(needs a Brew on Tab with an Equipment Profile, on the Recipe tab)' : '(needs the Brew Length on the Recipe tab)';
  };
  const live = { onChange: () => { changed(); sum(); } };
  const add = guard(() => { all.push({ name: '', type: grainTab ? 'grain' : levelFermTypes(rc).includes('adjunct') ? 'adjunct' : levelFermTypes(rc)[0], kg: null, yieldPct: null, color: null, addAfterBoil: false }); changed(); renderMenuPane(); });
  const del = (f, n) => guard(() => { if (!confirm(`Delete ${what} ${n}${f.name ? ` (${f.name})` : ''}?`)) return; all.splice(all.indexOf(f), 1); changed(); renderMenuPane(); });
  pane.append(h('div', { class: 'hopHead' }, h('h2', {}, grainTab ? 'Grains' : 'Fermentables'),
    op ? h('button', { class: 'hopAdd', onclick: add, title: `Add a ${what.toLowerCase()} line at the bottom` }, `${grainTab ? 'Add ' : ''}${what} `, h('b', {}, '+')) : ''));
  if (!mine.length) pane.append(h('p', { class: 'muted' }, grainTab ? 'No grains yet. Press Add Grain, or IMPORT a recipe on the Recipe tab.' : (levelFermTypes(rc).includes('sugar') ? 'No other fermentables. Press Add Fermentable for an adjunct, extract, sugar, fruit or juice.' : 'No extracts yet. Press Add Fermentable for a can of extract or dry extract.')));
  mine.forEach((f, i) => {
    const n = i + 1, F = end => `skn_rcp_${what}_${n}_${end}`, line = h('div', { class: 'rcRow hopLine fermLine' });
    line.append(rcBox('g', `${what} ${n}`, rcInput(f, 'name', { kind: 'text', ...c }), { wide: true, field: F('Name') }));
    const pp = h('input', { type: 'text', disabled: true, tabIndex: -1 }); pts.push([f, pp]);
    if (grainTab) line.append(rcBox('g', wLabel, rcInput(f, 'kg', { to: v => kgTo(v, W), from: v => toKg(v, W), ...live }), { field: F('Amount'), tip: 'Amount, in the grain weight standard picked on ☰ Menu > Default' }));
    else {
      // Amount in the line's own Measurement; Measurement and Type are select-only lists from the BeerXML standard
      const M = FERM_MEASURES[f.unit] ? f.unit : W;
      // the Recipe Level's Types (Rule 17.11: Levels 1 and 2 Extracts only); a line that already has another Type keeps it in its list
      const LT = levelFermTypes(rc), types = [...LT, ...(LT.includes(f.type) ? [] : [f.type])].map(k => [k, FERMENTABLE_TYPES[k] || k]);
      line.append(rcBox('g', 'Amount', rcInput(f, 'kg', { to: v => kgTo(v, M), from: v => toKg(v, M), ...live }), { field: F('Amount') }),
        rcBox('g', 'Measurement', rcInput({ unit: M }, 'unit', { kind: 'sel', list: Object.entries(FERM_MEASURES), onChange: () => {} }), { field: F('Measurement') }),
        rcBox('g', 'Type', rcInput(f, 'type', { kind: 'sel', list: types, onChange: () => { changed(); renderMenuPane(); } }), { field: F('Type') }));
      const ms = line.querySelector(`[data-field="${F('Measurement')}"] select`);
      ms.onchange = () => { f.unit = ms.value; changed(); renderMenuPane(); };
    }
    line.append(
      rcBox('g', 'Potential', rcInput(f, 'yieldPct', { d: 1, ...live }), { unit: '%', field: F('Potential'), tip: 'The yield: how much of its weight becomes sugar' }),
      rcBox('s', 'SRM', rcInput(f, 'color', { d: 1, ...c }), { field: F('SRM'), tip: 'The color' }),
      rcBox('c', pLabel, pp, { field: F('PPG_SG'), tip: `Gravity points: Potential x ${46.214} x pounds${grainTab || f.type === 'adjunct' ? ' x brewhouse efficiency' : ''} / gallons in the batch. They add up to the Expected Gravity on the Recipe tab` }));
    if (!grainTab && AFTER_BOIL_TYPES.includes(f.type)) line.append(h('div', { class: 'hopSw', 'data-field': F('After_Boil'), title: `Added after the boil (at flame out or in the fermenter)\nSkynet_Field ${F('After_Boil')}` },
      h('b', {}, 'After Boil'), rcSwitch(!!f.addAfterBoil, on => { f.addAfterBoil = on; changed(); })));
    if (op) line.append(h('button', { class: 'hopDel', onclick: del(f, n), title: `Delete ${what} ${n}` }, '🗑 Delete'));
    pane.append(line);
  });
  sum();
  pane.append(h('p', {}, `Total ${grainTab ? 'grain' : 'other fermentables'}: `, total, grainTab ? '. Calculate on the Recipe tab puts the Grain Wt. box together from the grains and adjuncts.' : '',
    ` Expected Gravity (all grains and fermentables): `, eg, '.'));
}

// ---- The Adjuncts tab (Fritz, 2026-10-31: "in a like manner" as the Grain and Fermentable tabs). BeerSmith and BeerXML
// call them Misc: Whirlfloc, yeast nutrient, gypsum, spices. Each line: Name, Amount, Measurement, Type, Use, Time and its
// unit. The dropdowns are select only, with the BeerXML lists. A Boil adjunct gets hop-style alerts (the Drops tab).
// Adjunct-type fermentables (flaked grains, they add sugar) stay on the Fermentable tab. Skynet_Fields skn_rcp_Adjunct_N_...
function rcAdjuncts(pane, rc, changed) {
  const all = rc.ingredients.miscs, op = can('operator'), c = { onChange: changed };
  const sel = (obj, key, list, rerender) => rcInput(obj, key, { kind: 'sel', list: [...list, ...(list.some(([v]) => v === obj[key]) || !obj[key] ? [] : [[obj[key], obj[key]]])], onChange: () => { changed(); if (rerender) renderMenuPane(); } });
  const add = pick => guard(() => { all.push({ ...pick, amount: null }); changed(); renderMenuPane(); })();
  // Adjunct + is a dropdown (Panel Update 9, item 28): a click on a common adjunct adds its line, Other adds an empty one
  const addSel = h('select', { class: 'hopAdd adjAdd', title: 'Pick one to add its line at the bottom: Other adds an empty line' },
    h('option', { value: '' }, 'Adjunct +'), ...COMMON_ADJUNCTS.map((a, i) => h('option', { value: i }, a.name)), h('option', { value: 'other' }, 'Other'));
  addSel.onchange = () => { const v = addSel.value; addSel.value = ''; if (v !== '') add(v === 'other' ? OTHER_ADJUNCT : COMMON_ADJUNCTS[+v]); };
  const del = (m, n) => guard(() => { if (!confirm(`Delete Adjunct ${n}${m.name ? ` (${m.name})` : ''}?`)) return; all.splice(all.indexOf(m), 1); changed(); renderMenuPane(); });
  pane.append(h('div', { class: 'hopHead' }, h('h2', {}, 'Adjuncts'), op ? addSel : ''));
  if (!all.length) pane.append(h('p', { class: 'muted' }, 'No adjuncts yet. Pick one from Adjunct +: Whirlfloc, Irish Moss, Yeast Nutrient, a water salt, a spice, or Other.'));
  all.forEach((m, i) => {
    const n = i + 1, F = end => `skn_rcp_Adjunct_${n}_${end}`, line = h('div', { class: 'rcRow hopLine' });
    line.append(rcBox('g', `Adjunct ${n}`, rcInput(m, 'name', { kind: 'text', ...c }), { wide: true, field: F('Name') }),
      rcBox('g', 'Amount', rcInput(m, 'amount', { d: 2, ...c }), { field: F('Amount') }),
      rcBox('g', 'Measurement', sel(m, 'unit', MISC_LINE_UNITS.map(x => [x, x])), { field: F('Measurement') }),
      rcBox('g', 'Type', sel(m, 'type', MISC_TYPES.map(x => [x, x])), { field: F('Type') }),
      rcBox('g', 'Use', sel(m, 'use', Object.entries(MISC_USES).filter(([k]) => k !== 'other'), true), { field: F('Use'), tip: 'When it goes in. A Boil adjunct gets an alert on brew day (the Drops tab)' }),
      rcBox('g', m.use === 'boil' ? 'Boil Min' : 'Time', rcInput(m, 'time', { d: 0, ...c }), { field: F('Time'), tip: m.use === 'boil' ? 'Minutes left in the boil when it goes in' : 'How long' }),
      rcBox('g', 'Time Unit', sel(m, 'timeUnit', Object.entries(MISC_TIME_UNITS)), { field: F('Time_Unit') }));
    if (op) line.append(h('button', { class: 'hopDel', onclick: del(m, n), title: `Delete Adjunct ${n}` }, '🗑 Delete'));
    pane.append(line);
  });
  pane.append(h('p', { class: 'muted' }, 'Flaked grains and other adjuncts that add sugar are on the Fermentable tab, so they count in the Expected Gravity.'));
}

// ---- The MASH tab (Fritz, 2026-10-31: "Mash Profile and Water Profiles can be built as well"). Pick a Mash Profile
// (Skynet Template or your own), or use the Recipe's own mash (from the recipe file or typed here). A picked profile shows
// read only; Copy into this Recipe makes it the Recipe's own mash to change. Lines: Step N, Temp, Time (skn_rcp_Mash_Step_N_...).
function rcMash(pane, rc, u, changed) {
  const op = can('operator'), mp = rcMashProfile(rc), TT = TU(u.tempUnit), c = { onChange: changed };
  rc.mash = rc.mash || { steps: [] }; rc.mash.steps = rc.mash.steps || [];
  const tmp = { d: 1, to: v => cTo(v, u.tempUnit), from: v => toC(v, u.tempUnit), ...c };
  const pTemp = v => v === null || v === undefined || v === '' ? '' : rcRound(cTo(mp.units === 'Metric' ? +v : fToC(+v), u.tempUnit), 1);
  const ro = v => h('input', { type: 'text', value: v ?? '', disabled: true, tabIndex: -1 });
  const was = rc.mashProfile ?? '';
  const pick = rcInput(rc, 'mashProfile', { kind: 'sel', list: [['', 'The Recipe\'s own mash (below)'], ...S.mashProfiles.map(x => [x.id, x.name]), ...(op ? [PROF_ADD] : [])],
    onChange: () => { if (rc.mashProfile === '__add__') { rc.mashProfile = was; pick.value = was; return newBrewProfile('mash', true); } changed(); renderMenuPane(); } });
  const copy = guard(() => {
    rc.mash = { ...rc.mash, profileName: mp.name, steps: [...mp.steps.map(s => ({ name: s.name, type: 'Infusion', tempC: mp.units === 'Metric' ? +s.temp : fToC(+s.temp), min: +s.time || 0 })),
      ...(mp.mashOutTemp ? [{ name: 'Mash Out', type: 'Temperature', tempC: mp.units === 'Metric' ? +mp.mashOutTemp : fToC(+mp.mashOutTemp), min: 10 }] : [])] };
    rc.spargeType = mp.sparge || 'batch'; if (mp.spargeTemp !== undefined && mp.spargeTemp !== null) rc.spargeTempC = mp.units === 'Metric' ? +mp.spargeTemp : fToC(+mp.spargeTemp);
    rc.spargeMinutes = mp.sparge === 'batch' ? mp.batchRest ?? null : null; rc.mashProfile = '';
    changed(); renderMenuPane(); toast(`"${mp.name}" copied into this Recipe. Press Save to keep it`);
  });
  const addStep = guard(() => { rc.mash.steps.push({ name: `Step ${rc.mash.steps.length + 1}`, type: 'Infusion', tempC: null, min: 0 }); changed(); renderMenuPane(); });
  pane.append(h('div', { class: 'hopHead' }, h('h2', {}, 'Mash'), op && !mp ? h('button', { class: 'hopAdd', onclick: addStep, title: 'Add a mash step at the bottom' }, 'Mash Step ', h('b', {}, '+')) : ''),
    h('div', { class: 'rcRow' }, rcBox('g', 'Mash Profile', pick, { wide: true, field: 'skn_rcp_Mash_Profile', tip: 'A Skynet Template, one of your own (☰ Menu > Mash Profile), or the Recipe\'s own mash' }),
      mp && op ? h('button', { onclick: copy, title: 'Make this profile the Recipe\'s own mash, to change it here' }, '⧉ Copy into this Recipe') : '',
      mp?.notes ? h('span', { class: 'muted' }, mp.notes) : ''));
  const steps = mp ? mp.steps : rc.mash.steps;
  if (!steps.length) pane.append(h('p', { class: 'muted' }, 'No mash steps. Pick a Mash Profile, or press Mash Step +.'));
  steps.forEach((s, i) => {
    const n = i + 1, F = end => `skn_rcp_Mash_Step_${n}_${end}`, line = h('div', { class: 'rcRow hopLine' });
    if (mp) line.append(rcBox('g', `Step ${n}`, ro(s.name), { wide: true, field: F('Name') }), rcBox('r', 'Temp', ro(pTemp(s.temp)), { unit: TT, field: F('Temp') }), rcBox('g', 'Time', ro(s.time), { unit: 'min', field: F('Time') }));
    else {
      line.append(rcBox('g', `Step ${n}`, rcInput(s, 'name', { kind: 'text', ...c }), { wide: true, field: F('Name') }), rcBox('r', 'Temp', rcInput(s, 'tempC', tmp), { unit: TT, field: F('Temp') }),
        rcBox('g', 'Time', rcInput(s, 'min', { d: 0, ...c }), { unit: 'min', field: F('Time') }));
      if (op) line.append(h('button', { class: 'hopDel', onclick: guard(() => { if (!confirm(`Delete Step ${n} (${s.name})?`)) return; rc.mash.steps.splice(i, 1); changed(); renderMenuPane(); }) }, '🗑 Delete'));
    }
    pane.append(line);
  });
  // the sparge: the profile's (read only), or the Recipe's (the same boxes as on the Recipe tab)
  pane.append(h('h3', {}, 'Sparge'), mp
    ? h('div', { class: 'rcRow' }, rcBox('g', 'Sparge Type', ro(SPARGE[mp.sparge] || mp.sparge)), rcBox('r', 'Sparge Temperature', ro(pTemp(mp.spargeTemp)), { unit: TT }),
      ...(mp.sparge === 'batch' ? [rcBox('g', 'Batch Rest', ro(mp.batchRest), { unit: 'min' })] : []), rcBox('r', 'Mash Out', ro(pTemp(mp.mashOutTemp)), { unit: TT, tip: 'Empty = no mash out' }))
    : h('div', { class: 'rcRow' }, rcBox('g', 'Sparge Type', rcInput(rc, 'spargeType', { kind: 'sel', list: [['batch', 'Batch'], ['fly', 'Fly'], ['none', 'No sparge']], ...c }), { field: 'skn_rcp_Sparge_Type' }),
      rcBox('r', 'Sparge Temperature', rcInput(rc, 'spargeTempC', tmp), { unit: TT, field: 'skn_rcp_Sparge_Temp' }),
      rcBox('g', 'Sparge Minutes', rcInput(rc, 'spargeMinutes', { d: 0, ...c }), { unit: 'min', field: 'skn_rcp_Sparge_Minutes' })));
  pane.append(h('p', { class: 'muted' }, mp ? `${mp.skynet ? 'A Skynet Template is read only.' : 'Change your own Mash Profiles on ☰ Menu > Mash Profile.'} Calculate on the Recipe tab uses its first step for the 1st Mash and the strike water.`
    : 'The Recipe\'s own mash. Calculate on the Recipe tab uses its first step for the 1st Mash and the strike water.'));
}
// ---- The Waters tab: the Water Profile picked and its minerals after the distilled or RO cut (skn_rcp_Water_...). The profile
// itself is changed on ☰ Menu > Water Profile. Below: the waters the recipe file listed.
function rcWaters(pane, rc, u, changed) {
  // none picked: Tap Water (Rule 17.12, its numbers on ☰ Menu > Default)
  const wp = S.waterProfiles.find(x => x.id === rc.waterProfile) || S.waterProfiles.find(x => x.tap), b = wp ? blendWater(wp) : {};
  const ro = v => h('input', { type: 'text', value: v ?? '', disabled: true, tabIndex: -1 });
  const pick = rcInput({ waterProfile: wp?.id ?? '' }, 'waterProfile', { kind: 'sel', list: [...S.waterProfiles.map(x => [x.id, x.name]), ...(can('operator') ? [PROF_ADD] : [])], onChange: () => {} });
  pick.addEventListener('change', () => { if (pick.value === '__add__') { pick.value = wp?.id ?? ''; return newBrewProfile('water', true); } rc.waterProfile = pick.value; changed(); renderMenuPane(); });
  pane.append(h('div', { class: 'hopHead' }, h('h2', {}, 'Waters')),
    h('div', { class: 'rcRow' }, rcBox('g', 'Water Profile', pick, { wide: true, field: 'skn_rcp_Water_Profile', tip: 'A Skynet water, or your own water report (☰ Menu > Water Profile)' }), wp?.notes && !wp.tap ? h('span', { class: 'muted' }, wp.notes) : ''));
  if (wp) {
    const [ions, rest] = [WATER_FIELDS.slice(0, WATER_IONS.length), WATER_FIELDS.slice(WATER_IONS.length)];
    pane.append(h('div', { class: 'rcRow' }, ...ions.map(([k, , key], i) => rcBox('c', WATER_IONS[i][1], ro(b[key]), { unit: 'ppm', field: k, tip: wp.distilledPct ? `${wp[key]} ppm in the water report, cut with ${wp.distilledPct}% distilled` : '' }))),
      h('div', { class: 'rcRow' }, rcBox('c', '% Distilled / RO', ro(+wp.distilledPct || 0), { unit: '%', field: rest[0][0] }), rcBox('c', 'SO4 : Cl', ro(b.so4cl ?? ''), { field: rest[1][0], tip: 'Above 2: crisp and hoppy. Below 1: round and malty' }),
        rcBox('c', 'pH', ro(wp.ph ?? ''), { field: rest[2][0] })),
      h('p', { class: 'muted' }, `${wp.skynet ? 'A Skynet water is read only: ☰ Menu > Water Profile > Add new ... copies it to make your own.' : wp.tap ? 'Fill in your Tap Water numbers on ☰ Menu > Default settings > Tap Water.' : 'Change it on ☰ Menu > Water Profile.'} The minerals show after the distilled or RO cut.`));
  }
  const W = rc.ingredients.waters || [];
  pane.append(h('h3', {}, 'Waters in the recipe file'), W.length ? '' : h('p', { class: 'muted' }, 'None.'),
    ...W.map((w, i) => h('div', { class: 'rcRow hopLine' }, rcBox('g', `Water ${i + 1}`, ro(w.name), { wide: true }), rcBox('b', 'Amount', ro(rcRound(lTo(w.liters, u.volumeUnit))), { unit: u.volumeUnit }),
      ...WATER_IONS.map(([k, l]) => rcBox('g', l.replace(/ \(.*/, ''), ro(w[k] ?? ''), { unit: 'ppm' })))));
}

// a Daughter Tab. Fritz sends the fields and layout of each later; until then each shows what the Recipe holds for it
function rcDaughter(pane, rc, u, changed, [k, t, about]) {
  const back = h('button', { onclick: () => { rcSub = 'recipe'; renderMenuPane(); } }, '◀ Back to the Recipe tab');
  if (k === 'hops') { rcHops(pane, rc, u, changed); pane.append(h('div', { class: 'bar' }, back)); return; }
  if (k === 'posthops') { rcPostHops(pane, rc, u, changed); pane.append(h('div', { class: 'bar' }, back)); return; }
  if (k === 'adjuncts') { rcAdjuncts(pane, rc, changed); pane.append(h('div', { class: 'bar' }, back)); return; }
  if (k === 'mash') { rcMash(pane, rc, u, changed); pane.append(h('div', { class: 'bar' }, back)); return; }
  if (k === 'yeast') { rcYeast(pane, rc, u, changed); pane.append(h('div', { class: 'bar' }, back)); return; }
  if (k === 'waters') { rcWaters(pane, rc, u, changed); pane.append(h('div', { class: 'bar' }, back)); return; }
  if (k === 'grain' || k === 'fermentables') { rcFerms(pane, rc, u, changed, k === 'grain'); pane.append(h('div', { class: 'bar' }, back)); return; }
  pane.append(h('p', {}, h('b', {}, about)), h('p', { class: 'muted rcSoon' }, `The fields and layout of the ${t} tab come next. Until then, here is what the Recipe holds for it.`));
  if (k === 'drops') rcDrops(pane, rc);
  pane.append(h('div', { class: 'bar' }, back));
}
// ---- The Yeast tab (OakBarn Brewery's Yeast layout, 2026-11-19: "Use it"). One line for each yeast, no limit: Name, Form, Amount, its own
// Unit (Packs, g, oz or ml, Rule 17.18), Attenuation % and the temperature range. ▸ More opens the rest under the line: Lab,
// Product ID, Type, Flocculation, Starter (and its size), Times cultured, Manufacture date, Notes. The amount is kept in its own
// unit, like an Adjunct line; the temperatures in °C and the starter in liters, shown in the Units (Rule 2.59). skn_rcp_Yeast_N_...
const rcYeastMore = new WeakSet();     // the yeast lines with More open
function rcYeast(pane, rc, u, changed) {
  rc.ingredients.yeasts = rc.ingredients.yeasts || [];
  const Y = rc.ingredients.yeasts, op = can('operator'), c = { onChange: changed, ro: !op }, TT = TU(u.tempUnit);
  const tmp = { d: 1, to: v => cTo(v, u.tempUnit), from: v => toC(v, u.tempUnit), ...c };
  // a select-only list; a value from a file that is not in it stays in its own list
  const sel = (obj, key, list, rerender) => rcInput(obj, key, { kind: 'sel', ro: !op, list: [['', ''], ...list.map(x => [x, x]), ...(list.includes(obj[key]) || !obj[key] ? [] : [[obj[key], obj[key]]])],
    onChange: () => { changed(); if (rerender) renderMenuPane(); } });
  const add = guard(() => { Y.push({ name: '', form: 'Dry', amount: 1, unit: 'Packs', attenuation: null, minTempC: null, maxTempC: null, lab: '', productId: '', type: 'Ale', flocculation: '', starter: false, starterL: null, timesCultured: null, mfgDate: '', notes: '' }); changed(); renderMenuPane(); });
  const del = (y, n) => guard(() => { if (!confirm(`Delete Yeast ${n}${y.name ? ` (${y.name})` : ''}?`)) return; Y.splice(Y.indexOf(y), 1); changed(); renderMenuPane(); });
  pane.append(h('div', { class: 'hopHead' }, h('h2', {}, 'Yeast'), op ? h('button', { class: 'hopAdd', onclick: add, title: 'Add a yeast line at the bottom' }, 'Yeast ', h('b', {}, '+')) : ''));
  if (!Y.length) pane.append(h('p', { class: 'muted' }, 'No yeast yet. Press Yeast +, or IMPORT a recipe on the Recipe tab.'));
  Y.forEach((y, i) => {
    const n = i + 1, F = end => `skn_rcp_Yeast_${n}_${end}`, open = rcYeastMore.has(y);
    const ms = rcInput({ unit: yeastUnitOf(y) }, 'unit', { kind: 'sel', list: Object.entries(YEAST_UNITS), ro: !op, onChange: () => {} });
    ms.addEventListener('change', () => { y.unit = ms.value; changed(); });
    const more = h('button', { onclick: () => { if (open) rcYeastMore.delete(y); else rcYeastMore.add(y); renderMenuPane(); }, title: 'Lab, Product ID, Type, Flocculation, Starter, Times cultured, Manufacture date and Notes' }, open ? '▾ More' : '▸ More');
    pane.append(h('div', { class: 'rcRow hopLine' },
      rcBox('k', `Yeast ${n}`, rcInput(y, 'name', { kind: 'text', ...c }), { wide: true, field: F('Name') }),
      rcBox('g', 'Form', sel(y, 'form', YEAST_FORMS), { field: F('Form') }),
      rcBox('g', 'Amount', rcInput(y, 'amount', { d: 2, ...c }), { field: F('Amount') }),
      rcBox('g', 'Unit', ms, { field: F('Measurement'), tip: 'This yeast\'s own unit: Packs, g, oz or ml. Most yeasts come in Packs' }),
      rcBox('g', 'Attenuation', rcInput(y, 'attenuation', { d: 1, ...c }), { unit: '%', field: F('Attenuation'), tip: 'How much of the sugar the yeast eats' }),
      rcBox('r', 'Min Temp', rcInput(y, 'minTempC', tmp), { unit: TT, field: F('Min_Temp'), tip: 'The lowest temperature it ferments at' }),
      rcBox('r', 'Max Temp', rcInput(y, 'maxTempC', tmp), { unit: TT, field: F('Max_Temp'), tip: 'The highest temperature it ferments at' }),
      more, op ? h('button', { class: 'hopDel', onclick: del(y, n), title: `Delete Yeast ${n}` }, '🗑 Delete') : ''));
    if (!open) return;
    const date = h('input', { type: 'date', value: y.mfgDate || '', ...(op ? {} : { disabled: true }) }); date.onchange = () => { y.mfgDate = date.value; changed(); };
    pane.append(h('div', { class: 'rcRow hopLine' },
      rcBox('g', 'Lab', rcInput(y, 'lab', { kind: 'text', ...c }), { field: F('Lab') }),
      rcBox('g', 'Product ID', rcInput(y, 'productId', { kind: 'text', ...c }), { field: F('Product_ID') }),
      rcBox('g', 'Type', sel(y, 'type', YEAST_TYPES), { field: F('Type') }),
      rcBox('g', 'Flocculation', sel(y, 'flocculation', YEAST_FLOCS), { field: F('Flocculation'), tip: 'How fast the yeast drops out' }),
      h('div', { class: 'hopSw', 'data-field': F('Starter'), title: `A yeast starter\nSkynet_Field ${F('Starter')}` }, h('b', {}, 'Starter'), rcSwitch(!!y.starter, on => { if (!op) return; y.starter = on; changed(); renderMenuPane(); })),
      y.starter ? rcBox('b', 'Starter Size', rcInput(y, 'starterL', { d: 2, to: v => lTo(v, u.volumeUnit), from: v => toL(v, u.volumeUnit), ...c }), { unit: u.volumeUnit, field: F('Starter_Size'), tip: 'Empty is fine' }) : '',
      rcBox('g', 'Times Cultured', rcInput(y, 'timesCultured', { d: 0, ...c }), { field: F('Times_Cultured') }),
      rcBox('g', 'Mfg Date', date, { field: F('Mfg_Date'), tip: 'The manufacture date on the pack, for how fresh it is' }),
      rcBox('g', 'Notes', rcInput(y, 'notes', { kind: 'text', ...c }), { wide: true, field: F('Notes') })));
  });
}
// Drops: the results only. Skynet's hop order, every alert (merged when two land together) and their voice files
function rcDrops(pane, rc) {
  const sch = hopSchedule(rc, S.config.brewDefaults || {}, S.boilProfiles.find(x => x.id === (rc.boilProfile || S.config.brewDefaults?.boilProfile)) || null), saved = rcView.schedule, same = !profDirty.recipe;
  const groups = h('table', { class: 'grid' }, h('thead', {}, h('tr', {}, h('th', {}, 'Order'), h('th', {}, 'Hop Group'), h('th', {}, 'When'), h('th', {}, 'What goes in'))),
    h('tbody', {}, ...sch.groups.map((g, i) => h('tr', {}, h('td', {}, i + 1), h('td', {}, g.group ?? ''), h('td', {}, g.label), h('td', {}, g.what)))));
  const alerts = h('table', { class: 'grid' }, h('thead', {}, h('tr', {}, h('th', {}, 'Minutes into the boil'), h('th', {}, 'Minutes left'), h('th', {}, 'Alert'), h('th', {}, 'Voice file (media/Audio/Hops)'))),
    h('tbody', {}, ...(same ? saved.alerts : sch.alerts).map(a => h('tr', { class: a.kind === 'drop' ? 'rcDrop' : '' }, h('td', {}, rcRound(a.at, 0)), h('td', {}, rcRound(a.left, 0)),
      h('td', { style: 'white-space:pre-line' }, (a.parts.length > 1 ? '⚠ ' : '') + a.text), h('td', {}, same ? voiceCell(a) : h('span', { class: 'muted' }, 'Save first'))))));
  const st = rcView.alerts || {}, run = { timer: '' };
  const timers = S.config.elements.filter(e => e.type === 'timer').map(e => [e.name, e.name]);
  pane.append(h('h3', {}, 'Hop order'), groups, h('h3', {}, `Alerts (${sch.alerts.length}) over a ${sch.boilTime} minute boil, ${sch.warnMinutes} minute warnings`), alerts,
    sch.conflicts.length ? h('ul', { class: 'rcList' }, ...sch.conflicts.map(x => h('li', {}, x.text))) : h('p', { class: 'muted' }, 'No two alerts land at the same time.'),
    // the alerts a Process sends when the brew gets there (Rule 17.20): hop_alert "Pre Boil", "Mash", "1st Wort", "Hop Stand High" ..., "Fermenter"
    h('h3', {}, `Alerts the Process sends (${sch.processAlerts.length})`),
    sch.processAlerts.length ? h('table', { class: 'grid' }, h('thead', {}, h('tr', {}, h('th', {}, 'When'), h('th', {}, 'Process line'), h('th', {}, 'Alert'), h('th', {}, 'Voice file (media/Audio/Hops)'))),
      h('tbody', {}, ...(same && saved.processAlerts ? saved.processAlerts : sch.processAlerts).map(a => h('tr', { class: a.kind === 'drop' ? 'rcDrop' : '' }, h('td', {}, HOP_ALERT_WHEN[a.which] || a.which),
        h('td', {}, h('code', {}, `hop_alert "${a.which}"`)), h('td', {}, a.text), h('td', {}, same ? voiceCell(a) : h('span', { class: 'muted' }, 'Save first')))))) : h('p', { class: 'muted' }, 'None: no Pre Boil (All Grain), Hop Stand or Fermenter hops.'),
    h('h3', {}, 'Hop alerts on brew day'), h('p', { class: 'muted' }, 'A Process starts them with start_hop_alerts (or start_hop_alerts "Boil_Timer" to follow the Boil timer) and stops them with stop_hop_alerts. Or start them here.'),
    h('div', { class: 'bar' }, h('span', {}, st.running ? `Running (${st.sent} of ${st.of} sent${st.timer ? `, following ${st.timer}` : ''})` : 'Not running'),
      can('operator') ? [rcInput(run, 'timer', { kind: 'sel', list: [['', 'Skynet clock (from now)'], ...timers] }),
        h('button', { onclick: guard(async () => { const r = await api('POST', '/ui/recipe/alerts', { action: 'start', timer: run.timer }); toast(r.text); await rcLoad(); renderMenuPane(); }) }, '▶ Start hop alerts'),
        h('button', { onclick: guard(async () => { const r = await api('POST', '/ui/recipe/alerts', { action: 'stop' }); toast(r.text); await rcLoad(); renderMenuPane(); }) }, '■ ' + safetyWord('Stop')),
        h('button', { title: 'Show and say the first alert now, to check the sound', onclick: () => (same ? saved : sch).alerts[0] ? hopAlert((same ? saved : sch).alerts[0]) : toast('No alerts', true) }, '🔊 Test the first alert')] : ''));
}
// when a Process sends each hop_alert (Rule 17.20)
const HOP_ALERT_WHEN = { 'Pre Boil': 'The Strike Water reaches Strike', Mash: 'Just after the Mash Timer starts', '1st Wort': 'Just before the First Run starts',
  'Hop Stand High': 'The wort is at Hop Stand High', 'Hop Stand Middle': 'The wort is at Hop Stand Middle', 'Hop Stand Low': 'The wort is at Hop Stand Low', Fermenter: 'Every Fermenter is filled' };
// the voice file of one alert: found, or the steps to make it by hand (a free text to voice web site, then put the file here)
function voiceCell(a) {
  const name = a.audio.split('/').pop();
  if (a.audioFound) return h('span', {}, '✔ ' + name);
  const up = h('input', { type: 'file', accept: '.mp3,.wav,.ogg,.m4a,audio/*', hidden: true });
  up.onchange = guard(async () => {
    const f = up.files[0]; up.value = ''; if (!f) return;
    await api('PUT', `/ui/recipe/audio?name=${encodeURIComponent(name)}`, f, true); await rcLoad(); renderMenuPane(); toast(`Voice file saved as media/Audio/Hops/${name}`);
  });
  return h('span', { class: 'rcVoice' }, h('span', { class: 'muted' }, 'None yet: the browser\'s own voice says it. '),
    h('button', { type: 'button', title: 'Copy the words to paste into the voice web site', onclick: () => navigator.clipboard?.writeText(a.speak).then(() => toast('Words copied: paste them into the voice site'), () => prompt('Copy these words', a.speak)) }, '1 Copy words'),
    h('a', { href: 'https://ttsmp3.com/', target: '_blank', rel: 'noopener', class: 'btnLink', title: 'A free text to voice web site: paste the words, pick a voice, press Download MP3' }, '2 Open voice site'),
    can('operator') ? h('button', { type: 'button', title: `Pick the MP3 you downloaded. It is saved as ${name} in media/Audio/Hops`, onclick: () => up.click() }, '3 Put the file here') : '', up);
}
// a hop alert on brew day: a bar that stays until closed, the alert sound (Default tab), then its voice file or the browser's voice
function hopAlert(a) {
  const d = S.config.brewDefaults || {};
  const bar = h('div', { class: 'alertBar hopAlertBar' + (a.kind === 'drop' ? ' drop' : ''), role: 'alert' }, h('span', { style: 'white-space:pre-line' }, (a.kind === 'drop' ? '🌿 ' : '⏰ ') + a.text),
    h('button', { title: 'Close', onclick: () => bar.remove() }, '✕'));
  document.body.append(bar);
  if (!soundOn) return;
  const speak = () => {
    if (a.audio && a.audioFound) return new Audio(soundUrl(a.audio)).play().catch(() => { });
    if (d.speakAlerts === false || !window.speechSynthesis) return;
    const ut = new SpeechSynthesisUtterance(a.speak || a.text);
    if (d.voiceName) { const v = speechSynthesis.getVoices().find(x => x.name === d.voiceName); if (v) ut.voice = v; }
    speechSynthesis.speak(ut);
  };
  // a web link that can't be reached goes straight on to the voice (Rule 7.20)
  if (d.hopAlertSound) { const s = new Audio(soundUrl(d.hopAlertSound)); let said = false; const once = () => { if (!said) { said = true; speak(); } }; s.onended = once; s.onerror = once; s.play().catch(once); } else speak();
}

// ---------------------------------------------------------------- start
$$('#views button').forEach(b => b.onclick = () => setView(b.dataset.view));
window.addEventListener('beforeunload', e => { if (dirty || (editing && JSON.stringify(draft) !== JSON.stringify(S.config))) { e.preventDefault(); e.returnValue = ''; } });
// ---------------------------------------------------------------- Config Editor (admin only)
// A backup copy is made before every save or restore (Rule 9.17), not on opening. Save checks the JSON before anything is written.
let cfgDirty = false, cfgProblem = null;
const openConfig = guard(async () => {
  if (cfgDirty) return;                       // keep unsaved work when coming back to the page
  const r = await api('POST', '/ui/config/open');
  setCfgText(r.text);
  $('#cfgFile').textContent = r.file;
  $('#cfgBackupNote').textContent = 'A backup copy is made in config/backups before every save or restore.';
});
function setCfgText(t) { $('#cfgCode').value = t; cfgDirty = false; cfgProblem = null; $('#cfgState').textContent = ''; renderCfgProblems(); fIdx = -1; refreshFind(false); }
function updateCfgGutter() {
  const n = $('#cfgCode').value.split('\n').length, bad = cfgProblem?.line;
  $('#cfgGutter').innerHTML = Array.from({ length: n }, (_, i) => i + 1 === bad ? `<span class="err">${i + 1}</span>` : i + 1).join('\n');
  $('#cfgGutter').scrollTop = $('#cfgCode').scrollTop;
}
function renderCfgProblems(checked) {
  const ul = $('#cfgProblems'); ul.innerHTML = '';
  if (cfgProblem) ul.append(h('li', { onclick: () => cfgGoto(cfgProblem) }, `Line ${cfgProblem.line}: ${cfgProblem.msg}`));
  else if (checked) ul.append(h('li', { class: 'ok' }, 'No problems found'));
  updateCfgGutter();
}
function cfgGoto({ line, col }) {
  const ta = $('#cfgCode'), lines = ta.value.split('\n');
  const at = lines.slice(0, line - 1).reduce((a, s) => a + s.length + 1, 0) + Math.max(0, (col || 1) - 1);
  ta.focus(); ta.setSelectionRange(at, Math.min(at + 1, ta.value.length));
  ta.scrollTop = Math.max(0, (line - 5) * 19.5); ta.scrollLeft = 0;
}
$('#cfgCode').addEventListener('input', () => { cfgDirty = true; $('#cfgState').textContent = '(not saved)'; updateCfgGutter(); refreshFind(false); });
$('#cfgCode').addEventListener('scroll', () => { $('#cfgGutter').scrollTop = $('#cfgCode').scrollTop; syncHl(); });
$('#cfgCode').addEventListener('keydown', ev => {
  if (ev.key === 'Tab') { ev.preventDefault(); document.execCommand('insertText', false, '  '); }
  if ((ev.ctrlKey || ev.metaKey) && ev.key.toLowerCase() === 's') { ev.preventDefault(); $('#cfgSave').click(); }
});
$('#cfgFind').onclick = () => findOpen() ? hideFind() : showFind();
$('#cfgCheck').onclick = guard(async () => {
  cfgProblem = (await api('POST', '/ui/config/check', $('#cfgCode').value, true)).problem; renderCfgProblems(true);
  if (cfgProblem) cfgGoto(cfgProblem);
});
$('#cfgSave').onclick = guard(async () => {
  const c = await api('POST', '/ui/config/check', $('#cfgCode').value, true);
  if (c.problem) { cfgProblem = c.problem; renderCfgProblems(); cfgGoto(cfgProblem); throw new Error('Not saved: line ' + c.problem.line + ': ' + c.problem.msg); }
  if (!await skyConfirm('Save the config file?\n\nRunning Processes are stopped and the boards reconnect. The old file is kept in config/backups.', { ok: '💾 Save' })) return;
  const r = await api('PUT', '/ui/config', $('#cfgCode').value, true);
  if (!r.ok) { cfgProblem = r.problem; renderCfgProblems(); cfgGoto(cfgProblem); throw new Error('Not saved: line ' + r.problem.line + ': ' + r.problem.msg); }
  cfgDirty = false; cfgProblem = null; $('#cfgState').textContent = ''; renderCfgProblems(true);
  $('#cfgBackupNote').textContent = 'Saved. The old file was copied to config/backups/' + r.backup;
  savedPop('Schema.json saved');
});
$('#cfgReload').onclick = () => { if (cfgDirty && !confirm('Throw away your unsaved changes?')) return; cfgDirty = false; openConfig(); };
$('#cfgBackups').onclick = guard(async () => {
  const list = await api('GET', '/ui/config/backups'), box = $('#cfgBackupList'); box.innerHTML = '';
  if (!list.length) box.append(h('div', { class: 'faRow muted' }, 'No backups yet.'));
  for (const b of list) box.append(h('div', { class: 'faRow cfgBk' },
    h('div', { class: 'faText' }, h('div', {}, new Date(b.time).toLocaleString()), h('div', { class: 'muted faLine' }, `${b.name}  (${Math.round(b.size / 1024)} KB)`)),
    h('button', { title: 'Show this backup in the editor; nothing changes until you press Save', onclick: guard(async ev => {
      ev.preventDefault();
      if (cfgDirty && !confirm('Throw away your unsaved changes?')) return;
      setCfgText(await api('GET', '/ui/config/backups/' + encodeURIComponent(b.name)));
      cfgDirty = true; $('#cfgState').textContent = `(showing backup ${b.name}, not saved)`; $('#cfgBackupDlg').close();
    }) }, 'Open'),
    h('button', { class: 'primary', onclick: guard(async ev => {
      ev.preventDefault();
      if (!await skyConfirm(`Put back the config from ${new Date(b.time).toLocaleString()}?\n\nRunning Processes are stopped and the boards reconnect. The current file is copied to config/backups first.`, { ok: '↩ Put back' })) return;
      const r = await api('POST', `/ui/config/backups/${encodeURIComponent(b.name)}/restore`);
      setCfgText(r.text); $('#cfgBackupDlg').close();
      $('#cfgBackupNote').textContent = `Restored ${b.name}. The file it replaced was copied to config/backups/${r.backup}`;
      toast('Config restored');
    }) }, 'Restore')));
  $('#cfgBackupDlg').showModal();
});
// Sharing Schemas between brewers (OakBarn Brewery, 2026-11-10, Rule 10.9): "a Notice about copywrites but no checking of an export
// or import between brewers"; "That is between the Brewers". Shown on Save as .json file and Open a Schema file, wherever they open.
const SHARE_NOTICE = 'Sharing with other brewers: Skynet does not check what is in a Schema file, going out or coming in. The pictures, sounds, names and anything else in it, and any copyright on them, are between the brewers.';
// Schema.json: Save as .json file. The file is named after the Schema version (Name_yyyymmddThhmm, ISO 8601) when it has one.
// The Schema list's "Export to share ..." opens the same dialog (Rule 10.9).
$('#cfgExport').onclick = guard(exportSchemaFile);
async function exportSchemaFile() {
  const sc = S.schemas || { list: [] }, act = sc.active?.id, list = [...sc.list].sort((a, b) => (b.id === act) - (a.id === act));
  if (!list.length) throw new Error('There is no Schema to save yet');
  const w = { id: act || list[0].id };
  const fields = [['id', 'Schema', 'sel', list.map(x => [x.id, x.id === act ? `${x.name}  (loaded)` : x.name])],
    ['_n', 'The file goes to the Downloads folder of this computer. It holds the Schema only (tabs, devices, widgets, pictures, pipes and its Equipment Profile drawing), not logins or panel settings.', 'note'],
    ['_c', SHARE_NOTICE, 'note']];
  if (cfgDirty) fields.push(['_d', 'The changes in the editor are not saved yet, so they are not in the file. Press Save first to include them.', 'note']);
  if (await dialog('Save a Schema as a .json file', fields, w) !== 'ok') return;
  readFields(w);
  const r = await api('GET', `/ui/schemas/${encodeURIComponent(w.id)}/export`);
  download(r.file, JSON.stringify(r.schema, null, 2), 'application/json');
  savedPop(`Saved ${r.file}`);
}
// Schema.json: Open a Schema file (Fritz, 2026-11-06). The BruControl Importer saves its Schema in the Brewing folder's Import
// subfolder (C:\Brewing\Import); a file saved with "Save as .json file" works too. It becomes a new Schema (Rule 15.4).
// A Schema file from another brewer goes in the same Import folder; the Schema list's "Import a brewer's Schema ..." opens this too (Rule 10.9).
$('#cfgImport').onclick = guard(importSchemaFile);
async function importSchemaFile() {
  const dir = await api('GET', '/ui/schemas/importfolder');
  const PC = '__pc';
  const opts = [...dir.files.map(f => [f.name, `${f.name}   (${f.modified})`]), [PC, 'A .json file on this computer…']];
  const w = { pick: dir.files[0]?.name ?? PC, load: false };
  const fields = [['pick', 'Schema file', 'sel', opts],
    ['_n', dir.exists ? `Files in the Import folder (${dir.folder}), newest first. The Importer saves its Schemas there.` : `The Import folder (${dir.folder}) is not there yet. The Importer makes it when it saves a Schema.`, 'note'],
    ['load', 'Load it now (the panel switches to it)', 'bool'],
    ['_p', 'The file becomes a new Schema; no Schema here is changed. Its Processes are added (a Process with the same name that differs is backed up first).', 'note'],
    ['_c', SHARE_NOTICE, 'note']];
  if (await dialog('Open a Schema file', fields, w) !== 'ok') return;
  readFields(w);
  let body, q = 'load=' + (w.load ? '1' : '0');
  if (w.pick === PC) {
    const inp = h('input', { type: 'file', accept: '.json,application/json' });
    const f = await new Promise(res => { inp.onchange = () => res(inp.files[0]); inp.click(); });
    if (!f) return;
    body = await f.text();
  } else q += '&file=' + encodeURIComponent(w.pick);
  if (w.load && !await okToSwitch(w.pick, 'Loading the Schema')) return;
  const r = await api('POST', '/ui/schemas/import?' + q, body ?? '', true);
  const p = r.processes;
  const lines = [`Schema "${r.made.name}" added.`,
    `Processes: ${p.written.length} added${p.renamed?.length ? ` (you already had ${p.renamed.length} with the same name, so these came in under a new name: ${p.renamed.join(', ')})` : ''}${p.same.length ? `, ${p.same.length} already the same` : ''}${p.failed.length ? `, ${p.failed.length} could not be written` : ''}.`];
  if (r.draft) lines.push('This is a first draft from the Importer (made without its questions).');
  if (r.warningCount) lines.push(`${r.warningCount} notes from the import${r.warningCount > 30 ? ' (the first 30)' : ''}:`, ...r.warnings.slice(0, 30).map(x => '• ' + x));
  if (w.load) await afterSchemaSwitch(`Schema "${r.made.name}" opened and loaded`);
  else { S.schemas = await api('GET', '/ui/schemas'); renderSchemaPick(); toast(`Schema "${r.made.name}" added. Pick it in the Schema list to load it.`); }
  alert(lines.join('\n'));
}
